C<pre><code>#include &lt;windows.h&gt;
#include &lt;stdio.h&gt;

void demonstrate_windows_memory_timing() {
    SIZE_T size = 100 * 1024 * 1024;  // 100MB

    // 1. 保留虚拟地址空间
    LPVOID ptr = VirtualAlloc(NULL, size, MEM_RESERVE, PAGE_READWRITE);
    printf("虚拟地址保留: %p\n", ptr);

    // 2. 提交物理内存（此时分配物理页）
    ptr = VirtualAlloc(ptr, size, MEM_COMMIT, PAGE_READWRITE);
    printf("物理内存提交完成\n");

    // 使用内存
    memset(ptr, 0xCC, size);

    // 3. 解除物理内存提交（物理内存可能立即释放）
    VirtualFree(ptr, size, MEM_DECOMMIT);
    printf("物理内存解除提交\n");
    // 此时物理页可能被回收，但虚拟地址空间仍保留

    // 4. 完全释放虚拟地址空间
    VirtualFree(ptr, 0, MEM_RELEASE);
    printf("虚拟地址空间完全释放\n");
}
</code></pre> <p>Windows物理内存释放时机： - 立即释放: <code>MEM_DECOMMIT</code> 立即将物理页标记为可用 - 工作集修剪: 系统内存压力大时自动从工作集移除物理页 - 进程退出: 进程终止时立即释放所有物理内存 - 页面文件: 修改的页面可能先写入页面文件再释放物理内存</p>

C<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;sys/mman.h&gt;
#include &lt;unistd.h&gt;
#include &lt;string.h&gt;

void demonstrate_linux_memory_timing() {
    size_t size = 100 * 1024 * 1024;  // 100MB

    // 1. 映射虚拟内存（延迟物理分配）
    void* ptr = mmap(NULL, size, PROT_READ|PROT_WRITE, 
                    MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);
    printf("虚拟内存映射: %p\n", ptr);

    // 2. 首次访问触发物理页分配
    memset(ptr, 0xAA, size);
    printf("物理内存实际分配完成\n");

    // 3. 解除映射（物理内存可能延迟释放）
    munmap(ptr, size);
    printf("虚拟内存解除映射\n");
    // 物理页可能仍在缓存中，直到系统需要内存时才真正回收
}

// 使用madvise主动控制物理内存释放
void proactive_memory_release() {
    size_t size = 100 * 1024 * 1024;
    void* ptr = mmap(NULL, size, PROT_READ|PROT_WRITE, 
                    MAP_PRIVATE|MAP_ANONYMOUS, -1, 0);

    memset(ptr, 0xBB, size);

    // 主动建议内核立即释放物理内存
    madvise(ptr, size, MADV_DONTNEED);
    printf("建议内核释放物理内存\n");

    // 但虚拟地址空间仍然有效，下次访问会重新分配零页
    munmap(ptr, size);
}
</code></pre> <p>Linux物理内存释放时机： - 延迟释放: <code>munmap</code> 后物理页可能保持在页面缓存中 - 内存压力释放: 当系统内存不足时通过kswapd回收 - 主动释放: <code>madvise(MADV_DONTNEED)</code> 立即释放物理页 - 进程退出: 进程终止时立即释放所有私有物理内存</p>

