    LPVOID pMem = VirtualAlloc(
        NULL,
        size,
        MEM_RESERVE | MEM_COMMIT,
        PAGE_READWRITE
    );

    if (pMem == NULL) {
        printf("VirtualAlloc failed: %d\n", GetLastError());
        return -1;
    }

    printf("Allocated at: %p\n", pMem);

    // 使用内存
    memset(pMem, 0xAA, size);

    // 查询内存信息
    MEMORY_BASIC_INFORMATION mbi;
    VirtualQuery(pMem, &amp;mbi, sizeof(mbi));
    printf("Region size: %zu bytes\n", mbi.RegionSize);

    // 修改保护属性为只读
    DWORD dwOldProtect;
    VirtualProtect(pMem, size, PAGE_READONLY, &amp;dwOldProtect);
    printf("Changed to read-only\n");

    // 释放内存
    VirtualFree(pMem, 0, MEM_RELEASE);
    printf("Memory released\n");

    return 0;
}
