);
</code></pre> <p>示例： C++<pre><code>#include &lt;windows.h&gt;
#include &lt;stdio.h&gt;

CRITICAL_SECTION cs;
int counter = 0;

DWORD WINAPI ThreadFunc(LPVOID param) {
    for (int i = 0; i &lt; 1000; i++) {
        EnterCriticalSection(&amp;cs);
        counter++;
        LeaveCriticalSection(&amp;cs);
    }
