    }

    WaitForMultipleObjects(10, threads, TRUE, INFINITE);

    printf("Counter: %d\n", counter);

    DeleteCriticalSection(&amp;cs);

    for (int i = 0; i &lt; 10; i++) {
        CloseHandle(threads[i]);
    }

    return 0;
}
