C++<pre><code>BOOL FindClose(
    HANDLE hFindFile
);
</code></pre> <p>WIN32_FIND_DATA结构： C++<pre><code>typedef struct _WIN32_FIND_DATA {
    DWORD    dwFileAttributes;
    FILETIME ftCreationTime;
    FILETIME ftLastAccessTime;
    FILETIME ftLastWriteTime;
    DWORD    nFileSizeHigh;
    DWORD    nFileSizeLow;
    DWORD    dwReserved0;
    DWORD    dwReserved1;
    TCHAR    cFileName[MAX_PATH];
    TCHAR    cAlternateFileName[14];
} WIN32_FIND_DATA;
</code></pre></p> <p>示例 - 列出目录内容： C++<pre><code>#include &lt;windows.h&gt;
#include &lt;stdio.h&gt;

void ListDirectory(const char* path) {
    WIN32_FIND_DATA findData;
    char searchPath[MAX_PATH];

    sprintf(searchPath, "%s\\*.*", path);

    HANDLE hFind = FindFirstFile(searchPath, &amp;findData);
    if (hFind == INVALID_HANDLE_VALUE) {
        printf("FindFirstFile failed: %d\n", GetLastError());
        return;
    }

    do {
        if (findData.dwFileAttributes &amp; FILE_ATTRIBUTE_DIRECTORY) {
            printf("[DIR] %s\n", findData.cFileName);
        } else {
            printf("[FILE] %s (%d bytes)\n", 
                findData.cFileName, 
                findData.nFileSizeLow);
        }
    } while (FindNextFile(hFind, &amp;findData));

    FindClose(hFind);
}

int main() {
    ListDirectory("C:\\");
    return 0;
}
</code></pre></p> <p>示例 - 递归查找文件： C++<pre><code>#include &lt;windows.h&gt;
#include &lt;stdio.h&gt;

void FindFilesRecursive(const char* path, const char* pattern) {
    WIN32_FIND_DATA findData;
    char searchPath[MAX_PATH];

    // 查找文件
    sprintf(searchPath, "%s\\%s", path, pattern);
    HANDLE hFind = FindFirstFile(searchPath, &amp;findData);

    if (hFind != INVALID_HANDLE_VALUE) {
        do {
            if (!(findData.dwFileAttributes &amp; FILE_ATTRIBUTE_DIRECTORY)) {
                printf("%s\\%s\n", path, findData.cFileName);
            }
        } while (FindNextFile(hFind, &amp;findData));
        FindClose(hFind);
    }

    // 递归查找子目录
    sprintf(searchPath, "%s\\*.*", path);
    hFind = FindFirstFile(searchPath, &amp;findData);

    if (hFind != INVALID_HANDLE_VALUE) {
        do {
            if (findData.dwFileAttributes &amp; FILE_ATTRIBUTE_DIRECTORY) {
                if (strcmp(findData.cFileName, ".") != 0 &amp;&amp; 
                    strcmp(findData.cFileName, "..") != 0) {
                    char subPath[MAX_PATH];
                    sprintf(subPath, "%s\\%s", path, findData.cFileName);
                    FindFilesRecursive(subPath, pattern);
                }
            }
        } while (FindNextFile(hFind, &amp;findData));
        FindClose(hFind);
    }
}

int main() {
    FindFilesRecursive("C:\\Projects", "*.cpp");
    return 0;
}
</code></pre></p>

