C++<pre><code>#include &lt;windows.h&gt;
#include &lt;stdio.h&gt;

void PrintValue(HKEY hKey, LPCWSTR valueName) {
    DWORD type;
    BYTE data[1024];
    DWORD dataSize = sizeof(data);

    LSTATUS status = RegQueryValueEx(hKey, valueName, NULL, &amp;type, data, &amp;dataSize);

    if (status != ERROR_SUCCESS) {
        wprintf(L"Failed to read %s\n", valueName);
        return;
    }

    switch (type) {
        case REG_SZ:
        case REG_EXPAND_SZ:
            wprintf(L"%s = %s\n", valueName, (LPCWSTR)data);
            break;
        case REG_DWORD:
            wprintf(L"%s = %d\n", valueName, *(DWORD*)data);
            break;
        case REG_QWORD:
            wprintf(L"%s = %lld\n", valueName, *(DWORD64*)data);
            break;
        case REG_BINARY:
            wprintf(L"%s = (binary, %d bytes)\n", valueName, dataSize);
            break;
        default:
            wprintf(L"%s = (type %d)\n", valueName, type);
            break;
    }
}

int main() {
    HKEY hKey;
    LSTATUS status = RegOpenKeyEx(
        HKEY_LOCAL_MACHINE,
        L"SOFTWARE\\Microsoft\\Windows\\CurrentVersion",
        0, KEY_READ, &amp;hKey
    );

    if (status == ERROR_SUCCESS) {
        PrintValue(hKey, L"ProductName");
        PrintValue(hKey, L"CurrentVersion");
        PrintValue(hKey, L"ProgramFilesPath");

        RegCloseKey(hKey);
    }

    return 0;
}
</code></pre>

C++<pre><code>BOOL CreatePipe(
    PHANDLE               hReadPipe,   // 读取句柄
    PHANDLE               hWritePipe,  // 写入句柄
    LPSECURITY_ATTRIBUTES lpPipeAttributes, // 安全属性
    DWORD                 nSize        // 缓冲区大小
);
</code></pre> <p>示例： C++<pre><code>#include &lt;windows.h&gt;
#include &lt;stdio.h&gt;

int main() {
    HANDLE hReadPipe, hWritePipe;
    SECURITY_ATTRIBUTES sa = {0};
    sa.nLength = sizeof(sa);
    sa.bInheritHandle = TRUE;

    if (!CreatePipe(&amp;hReadPipe, &amp;hWritePipe, &amp;sa, 0)) {
        printf("CreatePipe failed: %d\n", GetLastError());
        return -1;
    }

    // 创建子进程
    STARTUPINFO si = {0};
    PROCESS_INFORMATION pi = {0};
    si.cb = sizeof(si);
    si.hStdOutput = hWritePipe;
    si.hStdError = hWritePipe;
    si.dwFlags = STARTF_USESTDHANDLES;

    CreateProcess(NULL, "cmd.exe /c dir", NULL, NULL, TRUE, 0, NULL, NULL, &amp;si, &amp;pi);

    CloseHandle(hWritePipe);  // 关闭写入端

    // 读取输出
    char buffer[4096];
    DWORD bytesRead;
    while (ReadFile(hReadPipe, buffer, sizeof(buffer) - 1, &amp;bytesRead, NULL) &amp;&amp; bytesRead &gt; 0) {
        buffer[bytesRead] = '\0';
        printf("%s", buffer);
    }

    CloseHandle(hReadPipe);
    WaitForSingleObject(pi.hProcess, INFINITE);
    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);

    return 0;
}
</code></pre></p>

