        const char* response = "Hello from server!";
        DWORD bytesWritten;
        WriteFile(hPipe, response, strlen(response), &amp;bytesWritten, NULL);

        DisconnectNamedPipe(hPipe);
    }

    CloseHandle(hPipe);
    return 0;
}
