        FORMAT_MESSAGE_FROM_SYSTEM |
        FORMAT_MESSAGE_IGNORE_INSERTS,
        NULL,
        error,
        MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
        (LPTSTR)&amp;lpMsgBuf,
        0, NULL
    );

    wprintf(L"Error %d: %s\n", error, (LPCTSTR)lpMsgBuf);
    LocalFree(lpMsgBuf);
