    );

    if (bits &amp; EVENT_BIT_0) {
        // 事件0发生
    }
    if (bits &amp; EVENT_BIT_1) {
        // 事件1发生
    }
}

// 等待事件（全部）
void wait_all_events(void *pvParameters)
{
    EventBits_t bits;

    bits = xEventGroupWaitBits(
        event_group,
        EVENT_BIT_0 | EVENT_BIT_1,
        pdTRUE,
        pdTRUE,                      // 全部需要
        portMAX_DELAY
    );
}

