C<pre><code>uint16_t modbus_crc16(uint8_t *data, uint16_t len)
{
    uint16_t crc = 0xFFFF;
    for (uint16_t i = 0; i &lt; len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j &lt; 8; j++) {
            if (crc &amp; 0x0001)
                crc = (crc &gt;&gt; 1) ^ 0xA001;
            else
                crc &gt;&gt;= 1;
        }
    }
    return crc;
}

// 发送Modbus请求
void modbus_read_holding_regs(uint8_t slave, uint16_t addr, uint16_t count)
{
    uint8_t frame[8];
    frame[0] = slave;
    frame[1] = 0x03;  // 功能码
    frame[2] = addr &gt;&gt; 8;
    frame[3] = addr &amp; 0xFF;
    frame[4] = count &gt;&gt; 8;
    frame[5] = count &amp; 0xFF;

    uint16_t crc = modbus_crc16(frame, 6);
    frame[6] = crc &amp; 0xFF;
    frame[7] = crc &gt;&gt; 8;

    HAL_UART_Transmit(&amp;huart1, frame, 8, 100);
}
</code></pre>

C<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int read_adc(int channel)
{
    char path[64];
    char buf[16];
    int value;

    // 读取原始值
    snprintf(path, sizeof(path), 
             "/sys/bus/iio/devices/iio:device0/in_voltage%d_raw", 
             channel);
    FILE *f = fopen(path, "r");
    if (!f) return -1;
    fgets(buf, sizeof(buf), f);
    fclose(f);

    value = atoi(buf);

    // 读取缩放因子
    snprintf(path, sizeof(path),
             "/sys/bus/iio/devices/iio:device0/in_voltage%d_scale",
             channel);
    f = fopen(path, "r");
    if (f) {
        fgets(buf, sizeof(buf), f);
        fclose(f);
        float scale = atof(buf);
        return (int)(value * scale);
    }

    return value;
