C<pre><code>#include &lt;fcntl.h&gt;
#include &lt;unistd.h&gt;
#include &lt;sys/ioctl.h&gt;
#include &lt;linux/watchdog.h&gt;

int watchdog_fd;

void watchdog_init(void)
{
    watchdog_fd = open("/dev/watchdog", O_WRONLY);

    // 设置超时时间
    int timeout = 30;
    ioctl(watchdog_fd, WDIOC_SETTIMEOUT, &amp;timeout);

    // 获取超时时间
    ioctl(watchdog_fd, WDIOC_GETTIMEOUT, &amp;timeout);
}

// 喂狗
void watchdog_feed(void)
{
    write(watchdog_fd, "\0", 1);
    // 或
    ioctl(watchdog_fd, WDIOC_KEEPALIVE, 0);
}

// 关闭看门狗（需要支持）
void watchdog_disable(void)
{
    write(watchdog_fd, "V", 1);
    close(watchdog_fd);
}

// 使用示例
int main(void)
{
    watchdog_init();

    while (1) {
        // 执行任务

        watchdog_feed();
        sleep(10);
    }

    watchdog_disable();
    return 0;
}
