    struct rtc_time tm;

    ioctl(rtc_fd, RTC_RD_TIME, &amp;tm);

    printf("%04d-%02d-%02d %02d:%02d:%02d\n",
           tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
           tm.tm_hour, tm.tm_min, tm.tm_sec);
