void rtc_set_time(int year, int month, int day, int hour, int min, int sec)
{
    struct rtc_time tm;

    tm.tm_year = year - 1900;
    tm.tm_mon = month - 1;
    tm.tm_mday = day;
    tm.tm_hour = hour;
    tm.tm_min = min;
    tm.tm_sec = sec;

    ioctl(rtc_fd, RTC_SET_TIME, &amp;tm);
}

