void rtc_set_alarm(int hour, int min, int sec)
{
    struct rtc_wkalrm alarm;

    alarm.time.tm_hour = hour;
    alarm.time.tm_min = min;
    alarm.time.tm_sec = sec;
    alarm.enabled = 1;

    ioctl(rtc_fd, RTC_WKALM_SET, &amp;alarm);
