// 链式栈
typedef struct {
    StackNode *top;   // 栈顶指针（链表头）
    int size;          // 栈大小
} LinkedStack;

// 初始化栈
void initLinkedStack(LinkedStack *s) {
    s-&gt;top = NULL;
    s-&gt;size = 0;
}

// 判断栈是否为空
bool isEmptyLS(LinkedStack *s) {
    return s-&gt;top == NULL;
}

// 入栈（头插法）
void pushLS(LinkedStack *s, int value) {
    StackNode *newNode = (StackNode *)malloc(sizeof(StackNode));
    newNode-&gt;data = value;
    newNode-&gt;next = s-&gt;top;  // 新节点指向原栈顶
    s-&gt;top = newNode;         // 更新栈顶
    s-&gt;size++;
}

// 出栈
int popLS(LinkedStack *s) {
    if (isEmptyLS(s)) {
        printf("栈下溢!\n");
        return -1;
    }

    StackNode *temp = s-&gt;top;
    int value = temp-&gt;data;
    s-&gt;top = s-&gt;top-&gt;next;  // 栈顶下移
    free(temp);              // 释放节点
    s-&gt;size--;

    return value;
}

// 查看栈顶元素
int peekLS(LinkedStack *s) {
    if (isEmptyLS(s)) {
        printf("栈为空!\n");
        return -1;
    }
    return s-&gt;top-&gt;data;
}

// 释放栈内存
void freeLinkedStack(LinkedStack *s) {
    while (!isEmptyLS(s)) {
        popLS(s);
    }
}
