// 后缀表达式求值
int evaluatePostfix(char *expression) {
    ArrayStack stack;
    initStack(&amp;stack);

    char *token = strtok(expression, " ");

    while (token != NULL) {
        // 如果是数字，入栈
        if (isdigit(token[0])) {
            push(&amp;stack, atoi(token));
        } 
        // 如果是运算符，弹出两个操作数计算
        else {
            int b = pop(&amp;stack);  // 第二个操作数（先弹出）
            int a = pop(&amp;stack);  // 第一个操作数

            switch (token[0]) {
                case '+': push(&amp;stack, a + b); break;
                case '-': push(&amp;stack, a - b); break;
                case '*': push(&amp;stack, a * b); break;
                case '/': push(&amp;stack, a / b); break;
                case '^': push(&amp;stack, pow(a, b)); break;
            }
        }
        token = strtok(NULL, " ");
    }

    return pop(&amp;stack);
}
