C<pre><code>// 获取运算符优先级
int precedence(char op) {
    switch (op) {
        case '+':
        case '-': return 1;
        case '*':
        case '/': return 2;
        case '^': return 3;
        default: return 0;
    }
}

// 中缀表达式转后缀表达式
void infixToPostfix(char *infix, char *postfix) {
    ArrayStack stack;
    initStack(&amp;stack);
    int j = 0;

    for (int i = 0; infix[i] != '\0'; i++) {
        char c = infix[i];

        // 数字直接输出
        if (isdigit(c) || isalpha(c)) {
            postfix[j++] = c;
        }
        // 左括号入栈
        else if (c == '(') {
            push(&amp;stack, c);
        }
        // 右括号：弹出直到遇到左括号
        else if (c == ')') {
            while (!isEmpty(&amp;stack) &amp;&amp; peek(&amp;stack) != '(') {
                postfix[j++] = pop(&amp;stack);
            }
            pop(&amp;stack);  // 弹出左括号
        }
        // 运算符：弹出更高或相等优先级的运算符
        else {
            while (!isEmpty(&amp;stack) &amp;&amp; 
                   precedence(peek(&amp;stack)) &gt;= precedence(c)) {
                postfix[j++] = pop(&amp;stack);
            }
            push(&amp;stack, c);
        }
    }

    // 弹出剩余运算符
    while (!isEmpty(&amp;stack)) {
        postfix[j++] = pop(&amp;stack);
    }
    postfix[j] = '\0';
}
