typedef struct DQNode {
    int data;
    struct DQNode *prev;
    struct DQNode *next;
} DQNode;

// 双端队列
typedef struct {
    DQNode *front;
    DQNode *rear;
    int size;
} Deque;

// 初始化双端队列
void initDeque(Deque *dq) {
    dq-&gt;front = NULL;
    dq-&gt;rear = NULL;
    dq-&gt;size = 0;
}

// 从队首入队
void pushFront(Deque *dq, int value) {
    DQNode *newNode = (DQNode *)malloc(sizeof(DQNode));
    newNode-&gt;data = value;
    newNode-&gt;prev = NULL;
    newNode-&gt;next = dq-&gt;front;

    if (dq-&gt;front == NULL) {
        dq-&gt;rear = newNode;
    } else {
        dq-&gt;front-&gt;prev = newNode;
    }
    dq-&gt;front = newNode;
    dq-&gt;size++;
}

// 从队尾入队
void pushBack(Deque *dq, int value) {
    DQNode *newNode = (DQNode *)malloc(sizeof(DQNode));
    newNode-&gt;data = value;
    newNode-&gt;next = NULL;
    newNode-&gt;prev = dq-&gt;rear;

    if (dq-&gt;rear == NULL) {
        dq-&gt;front = newNode;
    } else {
        dq-&gt;rear-&gt;next = newNode;
    }
    dq-&gt;rear = newNode;
    dq-&gt;size++;
}

// 从队首出队
int popFront(Deque *dq) {
    if (dq-&gt;front == NULL) return -1;

    DQNode *temp = dq-&gt;front;
    int value = temp-&gt;data;

    dq-&gt;front = dq-&gt;front-&gt;next;
    if (dq-&gt;front == NULL) {
        dq-&gt;rear = NULL;
    } else {
        dq-&gt;front-&gt;prev = NULL;
    }

    free(temp);
    dq-&gt;size--;
    return value;
}

// 从队尾出队
int popBack(Deque *dq) {
    if (dq-&gt;rear == NULL) return -1;

    DQNode *temp = dq-&gt;rear;
    int value = temp-&gt;data;

    dq-&gt;rear = dq-&gt;rear-&gt;prev;
    if (dq-&gt;rear == NULL) {
        dq-&gt;front = NULL;
    } else {
        dq-&gt;rear-&gt;next = NULL;
    }

    free(temp);
    dq-&gt;size--;
    return value;
}
