C++<pre><code>#include &lt;vector&gt;
#include &lt;random&gt;
#include &lt;iostream&gt;

template&lt;typename K, typename V&gt;
class SkipList {
private:
    static const int MAX_LEVEL = 16;
    static constexpr double P = 0.5;

    struct Node {
        K key;
        V value;
        std::vector&lt;Node*&gt; forward;

        Node(K k, V v, int level) 
            : key(k), value(v), forward(level + 1, nullptr) {}
    };

    Node *header;
    int level;
    std::mt19937 rng;
    std::uniform_real_distribution&lt;double&gt; dist;

    int randomLevel() {
        int lvl = 0;
        while (dist(rng) &lt; P &amp;&amp; lvl &lt; MAX_LEVEL) {
            lvl++;
        }
        return lvl;
    }

public:
    SkipList() : level(0), rng(std::random_device{}()), dist(0, 1) {
        header = new Node(K{}, V{}, MAX_LEVEL);
    }

    ~SkipList() {
        Node *curr = header-&gt;forward[0];
        while (curr) {
            Node *temp = curr;
            curr = curr-&gt;forward[0];
            delete temp;
        }
        delete header;
    }

    // 查找
    V* search(const K&amp; key) {
        Node *curr = header;

        for (int i = level; i &gt;= 0; i--) {
            while (curr-&gt;forward[i] &amp;&amp; curr-&gt;forward[i]-&gt;key &lt; key) {
                curr = curr-&gt;forward[i];
            }
        }

        curr = curr-&gt;forward[0];
        return (curr &amp;&amp; curr-&gt;key == key) ? &amp;curr-&gt;value : nullptr;
    }

    // 插入
    void insert(const K&amp; key, const V&amp; value) {
        std::vector&lt;Node*&gt; update(MAX_LEVEL + 1, nullptr);
        Node *curr = header;

        for (int i = level; i &gt;= 0; i--) {
            while (curr-&gt;forward[i] &amp;&amp; curr-&gt;forward[i]-&gt;key &lt; key) {
                curr = curr-&gt;forward[i];
            }
            update[i] = curr;
        }

        curr = curr-&gt;forward[0];

        if (curr &amp;&amp; curr-&gt;key == key) {
            curr-&gt;value = value;
            return;
        }

        int lvl = randomLevel();

        if (lvl &gt; level) {
            for (int i = level + 1; i &lt;= lvl; i++) {
                update[i] = header;
            }
            level = lvl;
        }

        Node *newNode = new Node(key, value, lvl);

        for (int i = 0; i &lt;= lvl; i++) {
            newNode-&gt;forward[i] = update[i]-&gt;forward[i];
            update[i]-&gt;forward[i] = newNode;
        }
    }

    // 删除
    bool remove(const K&amp; key) {
        std::vector&lt;Node*&gt; update(MAX_LEVEL + 1, nullptr);
        Node *curr = header;

        for (int i = level; i &gt;= 0; i--) {
            while (curr-&gt;forward[i] &amp;&amp; curr-&gt;forward[i]-&gt;key &lt; key) {
                curr = curr-&gt;forward[i];
            }
            update[i] = curr;
        }

        curr = curr-&gt;forward[0];

        if (!curr || curr-&gt;key != key) {
            return false;
        }

        for (int i = 0; i &lt;= level; i++) {
            if (update[i]-&gt;forward[i] != curr) break;
            update[i]-&gt;forward[i] = curr-&gt;forward[i];
        }

        delete curr;

        while (level &gt; 0 &amp;&amp; header-&gt;forward[level] == nullptr) {
            level--;
        }

        return true;
    }

    // 打印结构
    void print() {
        for (int i = level; i &gt;= 0; i--) {
            std::cout &lt;&lt; "Level " &lt;&lt; i &lt;&lt; ": ";
            Node *curr = header-&gt;forward[i];
            while (curr) {
                std::cout &lt;&lt; curr-&gt;key &lt;&lt; " ";
                curr = curr-&gt;forward[i];
            }
            std::cout &lt;&lt; std::endl;
        }
    }
};
