C<pre><code>// 计算滑动窗口内的最大和
int slidingWindowMaxSum(int arr[], int n, int k) {
    CircularQueue *q = createQueue(k);
    int maxSum = 0, sum = 0;

    for (int i = 0; i &lt; n; i++) {
        sum += arr[i];
        enqueue(q, arr[i]);

        // 如果窗口超过k，移除最旧的元素
        if (size(q) &gt; k) {
            int old;
            dequeue(q, &amp;old);
            sum -= old;
        }

        // 更新最大和
        if (size(q) == k &amp;&amp; sum &gt; maxSum) {
            maxSum = sum;
        }
    }

    freeQueue(q);
    return maxSum;
}
