template&lt;typename T, typename Compare = std::less&lt;T&gt;&gt;
class PriorityQueue {
private:
    std::vector&lt;T&gt; data;  // 从索引0开始
    Compare comp;         // 比较器

    // 上浮操作
    void swim(int index) {
        while (index &gt; 0) {
            int parent = (index - 1) / 2;
            if (comp(data[parent], data[index])) {
                std::swap(data[parent], data[index]);
                index = parent;
            } else {
                break;
            }
        }
    }

    // 下沉操作
    void sink(int index) {
        int n = data.size();
        while (2 * index + 1 &lt; n) {
            int left = 2 * index + 1;
            int right = 2 * index + 2;
            int target = index;

            // 选择优先级更高的子节点
            if (left &lt; n &amp;&amp; comp(data[target], data[left])) {
                target = left;
            }
            if (right &lt; n &amp;&amp; comp(data[target], data[right])) {
                target = right;
            }

            if (target == index) break;
            std::swap(data[index], data[target]);
            index = target;
        }
    }

public:
    PriorityQueue() = default;

    void push(const T&amp; value) {
        data.push_back(value);
        swim(data.size() - 1);
    }

    void pop() {
        if (data.empty()) return;
        data[0] = data.back();
        data.pop_back();
        if (!data.empty()) sink(0);
    }

    T top() const { return data.front(); }
    bool empty() const { return data.empty(); }
    size_t size() const { return data.size(); }
};

