C<pre><code>// 查找最大值节点
BSTNode* findMax(BSTNode *root) {
    while (root-&gt;right != NULL) {
        root = root-&gt;right;
    }
    return root;
}

// 查找前驱
BSTNode* predecessor(BSTNode *root, BSTNode *node) {
    // 如果有左子树，前驱是左子树的最大值
    if (node-&gt;left != NULL) {
        return findMax(node-&gt;left);
    }

    // 否则，向上找第一个向右转的祖先
    BSTNode *pred = NULL;
    while (root != NULL) {
        if (node-&gt;data &gt; root-&gt;data) {
            pred = root;
            root = root-&gt;right;
        } else if (node-&gt;data &lt; root-&gt;data) {
            root = root-&gt;left;
        } else {
            break;
        }
    }
    return pred;
}

// 查找后继
BSTNode* successor(BSTNode *root, BSTNode *node) {
    // 如果有右子树，后继是右子树的最小值
    if (node-&gt;right != NULL) {
        return findMin(node-&gt;right);
    }

    // 否则，向上找第一个向左转的祖先
    BSTNode *succ = NULL;
    while (root != NULL) {
        if (node-&gt;data &lt; root-&gt;data) {
            succ = root;
            root = root-&gt;left;
        } else if (node-&gt;data &gt; root-&gt;data) {
            root = root-&gt;right;
        } else {
            break;
        }
    }
    return succ;
}
