C++<pre><code>template&lt;typename T&gt;
class BST {
private:
    struct Node {
        T data;
        Node *left, *right;
        Node(T val) : data(val), left(nullptr), right(nullptr) {}
    };

    Node *root;

    Node* insert(Node *node, T data) {
        if (!node) return new Node(data);
        if (data &lt; node-&gt;data) 
            node-&gt;left = insert(node-&gt;left, data);
        else if (data &gt; node-&gt;data) 
            node-&gt;right = insert(node-&gt;right, data);
        return node;
    }

    Node* findMin(Node *node) {
        while (node &amp;&amp; node-&gt;left) node = node-&gt;left;
        return node;
    }

    Node* remove(Node *node, T data) {
        if (!node) return nullptr;
        if (data &lt; node-&gt;data) 
            node-&gt;left = remove(node-&gt;left, data);
        else if (data &gt; node-&gt;data) 
            node-&gt;right = remove(node-&gt;right, data);
        else {
            if (!node-&gt;left) {
                Node *temp = node-&gt;right;
                delete node;
                return temp;
            }
            if (!node-&gt;right) {
                Node *temp = node-&gt;left;
                delete node;
                return temp;
            }
            Node *succ = findMin(node-&gt;right);
            node-&gt;data = succ-&gt;data;
            node-&gt;right = remove(node-&gt;right, succ-&gt;data);
        }
        return node;
    }

    void inorder(Node *node, std::vector&lt;T&gt;&amp; result) {
        if (!node) return;
        inorder(node-&gt;left, result);
        result.push_back(node-&gt;data);
        inorder(node-&gt;right, result);
    }

public:
    BST() : root(nullptr) {}

    void insert(T data) { root = insert(root, data); }
    void remove(T data) { root = remove(root, data); }

    bool search(T data) {
        Node *curr = root;
        while (curr) {
            if (data == curr-&gt;data) return true;
            curr = data &lt; curr-&gt;data ? curr-&gt;left : curr-&gt;right;
        }
        return false;
    }

    std::vector&lt;T&gt; inorder() {
        std::vector&lt;T&gt; result;
        inorder(root, result);
        return result;
    }
};
