    if (root-&gt;data &lt; low) {
        return rangeSumBST(root-&gt;right, low, high);
    }
    // 当前值大于 high，只需搜索左子树
    if (root-&gt;data &gt; high) {
        return rangeSumBST(root-&gt;left, low, high);
    }

    // 当前值在范围内，累加并搜索左右子树
    return root-&gt;data + 
           rangeSumBST(root-&gt;left, low, high) + 
           rangeSumBST(root-&gt;right, low, high);
}
