    int bf = getBalance(node);

    // LL 型: 左子树过高，且左子节点的左子树更高或等高
    if (bf &gt; 1) {
        if (getBalance(node-&gt;left) &lt; 0) {
            // LR 型: 先对左子树左旋
            node-&gt;left = leftRotate(node-&gt;left);
        }
        // 右旋
        return rightRotate(node);
