    // RR 型: 右子树过高，且右子节点的右子树更高或等高
    if (bf &lt; -1) {
        if (getBalance(node-&gt;right) &gt; 0) {
            // RL 型: 先对右子树右旋
            node-&gt;right = rightRotate(node-&gt;right);
        }
        // 左旋
        return leftRotate(node);
    }

    // 已经平衡，直接返回
    return node;
}
