C<pre><code>void insertFixup(RBNode **root, RBNode *z) {
    // 当父节点是红色时需要修复
    while (z-&gt;parent-&gt;color == RED) {
        if (z-&gt;parent == z-&gt;parent-&gt;parent-&gt;left) {
            // 父节点是祖父的左孩子
            RBNode *y = z-&gt;parent-&gt;parent-&gt;right;  // 叔节点

            if (y-&gt;color == RED) {
                // 情况1: 叔节点是红色
                z-&gt;parent-&gt;color = BLACK;
                y-&gt;color = BLACK;
                z-&gt;parent-&gt;parent-&gt;color = RED;
                z = z-&gt;parent-&gt;parent;  // 上移到祖父
            } else {
                if (z == z-&gt;parent-&gt;right) {
                    // 情况2: z 是右孩子
                    z = z-&gt;parent;
                    leftRotate(root, z);
                }
                // 情况3: z 是左孩子
                z-&gt;parent-&gt;color = BLACK;
                z-&gt;parent-&gt;parent-&gt;color = RED;
                rightRotate(root, z-&gt;parent-&gt;parent);
            }
        } else {
            // 父节点是祖父的右孩子（对称情况）
            RBNode *y = z-&gt;parent-&gt;parent-&gt;left;  // 叔节点

            if (y-&gt;color == RED) {
                // 情况1
                z-&gt;parent-&gt;color = BLACK;
                y-&gt;color = BLACK;
                z-&gt;parent-&gt;parent-&gt;color = RED;
                z = z-&gt;parent-&gt;parent;
            } else {
                if (z == z-&gt;parent-&gt;left) {
                    // 情况2
                    z = z-&gt;parent;
                    rightRotate(root, z);
                }
                // 情况3
                z-&gt;parent-&gt;color = BLACK;
                z-&gt;parent-&gt;parent-&gt;color = RED;
                leftRotate(root, z-&gt;parent-&gt;parent);
            }
        }
    }
    // 根节点必须是黑色
    (*root)-&gt;color = BLACK;
}
