C<pre><code>typedef struct {
    int *data;       // 数据数组
    int size;        // 当前元素数量
    int capacity;    // 容量
} MaxHeap;

// 初始化堆
void initHeap(MaxHeap *heap, int capacity) {
    heap-&gt;data = (int*)malloc(sizeof(int) * capacity);
    heap-&gt;size = 0;
    heap-&gt;capacity = capacity;
}

// 交换两个元素
void swap(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

// 上浮操作
void swim(MaxHeap *heap, int index) {
    while (index &gt; 0) {
        int parent = (index - 1) / 2;
        if (heap-&gt;data[index] &lt;= heap-&gt;data[parent]) {
            break;  // 满足堆性质
        }
        swap(&amp;heap-&gt;data[index], &amp;heap-&gt;data[parent]);
        index = parent;
    }
}

// 下沉操作
void sink(MaxHeap *heap, int index) {
    int n = heap-&gt;size;
    while (2 * index + 1 &lt; n) {
        int left = 2 * index + 1;
        int right = 2 * index + 2;
        int largest = index;

        // 找出较大的子节点
        if (left &lt; n &amp;&amp; heap-&gt;data[left] &gt; heap-&gt;data[largest]) {
            largest = left;
        }
        if (right &lt; n &amp;&amp; heap-&gt;data[right] &gt; heap-&gt;data[largest]) {
            largest = right;
        }

        if (largest == index) break;  // 满足堆性质

        swap(&amp;heap-&gt;data[index], &amp;heap-&gt;data[largest]);
        index = largest;
    }
}

// 插入元素
void insert(MaxHeap *heap, int value) {
    // 扩容
    if (heap-&gt;size &gt;= heap-&gt;capacity) {
        heap-&gt;capacity *= 2;
        heap-&gt;data = (int*)realloc(heap-&gt;data, sizeof(int) * heap-&gt;capacity);
    }

    heap-&gt;data[heap-&gt;size] = value;  // 添加到末尾
    swim(heap, heap-&gt;size);          // 上浮
    heap-&gt;size++;
}

// 删除并返回堆顶
int extractMax(MaxHeap *heap) {
    if (heap-&gt;size == 0) return -1;

    int max = heap-&gt;data[0];              // 保存堆顶
    heap-&gt;data[0] = heap-&gt;data[heap-&gt;size - 1];  // 末尾移到堆顶
    heap-&gt;size--;
    sink(heap, 0);                        // 下沉

    return max;
}

// 获取堆顶
int peek(MaxHeap *heap) {
    if (heap-&gt;size == 0) return -1;
    return heap-&gt;data[0];
}

// 建堆
void buildHeap(MaxHeap *heap, int arr[], int n) {
    heap-&gt;size = n;
    for (int i = 0; i &lt; n; i++) {
        heap-&gt;data[i] = arr[i];
    }

    // 从最后一个非叶子节点开始下沉
    for (int i = n / 2 - 1; i &gt;= 0; i--) {
        sink(heap, i);
    }
}
