    // 在当前节点找关键字位置
    int idx = findKey(root, key);

    // 如果找到关键字
    if (idx &lt; root-&gt;keyCount &amp;&amp; root-&gt;keys[idx] == key) {
        *pos = idx;
        return root;
    }

    // 如果是叶子节点，查找失败
    if (root-&gt;isLeaf) return NULL;

    // 递归查找子树
    return search(root-&gt;children[idx], key, pos);
