class Trie {
private:
    struct Node {
        std::vector&lt;std::unique_ptr&lt;Node&gt;&gt; children;
        bool isEnd;
        Node() : children(26), isEnd(false) {}
    };

    std::unique_ptr&lt;Node&gt; root;

    void collectAll(Node* node, std::string&amp; prefix, std::vector&lt;std::string&gt;&amp; result) {
        if (node-&gt;isEnd) result.push_back(prefix);
        for (int i = 0; i &lt; 26; i++) {
            if (node-&gt;children[i]) {
                prefix.push_back('a' + i);
                collectAll(node-&gt;children[i].get(), prefix, result);
                prefix.pop_back();
            }
        }
    }

public:
    Trie() : root(std::make_unique&lt;Node&gt;()) {}

    void insert(const std::string&amp; word) {
        Node* curr = root.get();
        for (char c : word) {
            int index = c - 'a';
            if (!curr-&gt;children[index]) {
                curr-&gt;children[index] = std::make_unique&lt;Node&gt;();
            }
            curr = curr-&gt;children[index].get();
        }
        curr-&gt;isEnd = true;
    }

    bool search(const std::string&amp; word) {
        Node* curr = root.get();
        for (char c : word) {
            int index = c - 'a';
            if (!curr-&gt;children[index]) return false;
            curr = curr-&gt;children[index].get();
        }
        return curr-&gt;isEnd;
    }

    bool startsWith(const std::string&amp; prefix) {
        Node* curr = root.get();
        for (char c : prefix) {
            int index = c - 'a';
            if (!curr-&gt;children[index]) return false;
            curr = curr-&gt;children[index].get();
        }
        return true;
    }

    std::vector&lt;std::string&gt; autocomplete(const std::string&amp; prefix) {
        Node* curr = root.get();
        for (char c : prefix) {
            int index = c - 'a';
            if (!curr-&gt;children[index]) return {};
            curr = curr-&gt;children[index].get();
        }

        std::vector&lt;std::string&gt; result;
        std::string p = prefix;
        collectAll(curr, p, result);
        return result;
    }
};
