C++<pre><code>template&lt;typename T&gt;
class BIT {
private:
    std::vector&lt;T&gt; tree;
    int n;

public:
    BIT(int size) : n(size), tree(size + 1, 0) {}

    void update(int index, T value) {
        while (index &lt;= n) {
            tree[index] += value;
            index += index &amp; (-index);
        }
    }

    T query(int index) {
        T sum = 0;
        while (index &gt; 0) {
            sum += tree[index];
            index -= index &amp; (-index);
        }
        return sum;
    }

    T rangeQuery(int l, int r) {
        return query(r) - query(l - 1);
    }

    // 二分查找第k小（需要值域树状数组）
    int findKth(int k) {
        int pos = 0;
        int bitMask = 1;
        while (bitMask &lt;= n) bitMask &lt;&lt;= 1;
        bitMask &gt;&gt;= 1;

        for (; bitMask; bitMask &gt;&gt;= 1) {
            int next = pos + bitMask;
            if (next &lt;= n &amp;&amp; tree[next] &lt; k) {
                k -= tree[next];
                pos = next;
            }
        }
        return pos + 1;
    }
};
