C<pre><code>int lcaBinaryLifting(int u, int v) {
    // 确保 u 是更深的节点
    if (depth[u] &lt; depth[v]) {
        int temp = u; u = v; v = temp;
    }

    // 将 u 向上跳到与 v 同一深度
    int diff = depth[u] - depth[v];
    for (int j = 0; j &lt; maxLog; j++) {
        if ((diff &gt;&gt; j) &amp; 1) {
            u = parent[u][j];
        }
    }

    // 如果 u == v，则 v 就是 LCA
    if (u == v) return u;

    // 同时向上跳，找到 LCA
    for (int j = maxLog - 1; j &gt;= 0; j--) {
        if (parent[u][j] != parent[v][j]) {
            u = parent[u][j];
            v = parent[v][j];
        }
    }

    return parent[u][0];
}
