        parentSet[x] = findSet(parentSet[x]);
    }
    return parentSet[x];
}

void unionSet(int x, int y) {
    parentSet[findSet(x)] = findSet(y);
}

void tarjan(int u, int *adj[], int n) {
    parentSet[u] = u;
    ancestor[u] = u;

    // 遍历子树
    for (int v = 0; v &lt; n; v++) {
        if (adj[u][v] &amp;&amp; !visited[v]) {
            tarjan(v, adj, n);
            unionSet(v, u);
            ancestor[findSet(u)] = u;
        }
    }

    visited[u] = 1;

    // 回答查询
    Query *q = queries[u];
    while (q != NULL) {
        if (visited[q-&gt;v]) {
            lcaResult[q-&gt;index] = ancestor[findSet(q-&gt;v)];
        }
        q = q-&gt;next;
    }
