C++<pre><code>#include &lt;vector&gt;
#include &lt;algorithm&gt;

class LCA {
private:
    std::vector&lt;std::vector&lt;int&gt;&gt; adj;
    std::vector&lt;std::vector&lt;int&gt;&gt; parent;
    std::vector&lt;int&gt; depth;
    int n, maxLog;

    void dfs(int u, int p, int d) {
        parent[u][0] = p;
        depth[u] = d;

        for (int v : adj[u]) {
            if (v != p) {
                dfs(v, u, d + 1);
            }
        }
    }

public:
    LCA(int n) : n(n), adj(n + 1), depth(n + 1) {
        maxLog = 0;
        while ((1 &lt;&lt; maxLog) &lt;= n) maxLog++;
        parent.assign(n + 1, std::vector&lt;int&gt;(maxLog, -1));
    }

    void addEdge(int u, int v) {
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    void build(int root) {
        dfs(root, -1, 0);

        for (int j = 1; j &lt; maxLog; j++) {
            for (int i = 1; i &lt;= n; i++) {
                if (parent[i][j - 1] != -1) {
                    parent[i][j] = parent[parent[i][j - 1]][j - 1];
                }
            }
        }
    }

    int lca(int u, int v) {
        if (depth[u] &lt; depth[v]) std::swap(u, v);

        int diff = depth[u] - depth[v];
        for (int j = 0; j &lt; maxLog; j++) {
            if ((diff &gt;&gt; j) &amp; 1) {
                u = parent[u][j];
            }
        }

        if (u == v) return u;

        for (int j = maxLog - 1; j &gt;= 0; j--) {
            if (parent[u][j] != parent[v][j]) {
                u = parent[u][j];
                v = parent[v][j];
            }
        }

        return parent[u][0];
    }

    int dist(int u, int v) {
        return depth[u] + depth[v] - 2 * depth[lca(u, v)];
    }

    // 判断 a 是否在 u 到 v 的路径上
    bool onPath(int a, int u, int v) {
        int l = lca(u, v);
        return lca(a, u) == a &amp;&amp; lca(a, v) == l;
    }

    // 求 u 到 v 路径上的第 k 个节点
    int kthNode(int u, int v, int k) {
        int l = lca(u, v);
        int d1 = depth[u] - depth[l];

        if (k &lt;= d1) {
            // 在 u 到 l 的路径上
            for (int j = 0; j &lt; maxLog; j++) {
                if ((k &gt;&gt; j) &amp; 1) {
                    u = parent[u][j];
                }
            }
            return u;
        } else {
            // 在 l 到 v 的路径上
            int d2 = depth[v] - depth[l];
            k = d1 + d2 - k;
            for (int j = 0; j &lt; maxLog; j++) {
                if ((k &gt;&gt; j) &amp; 1) {
                    v = parent[v][j];
                }
            }
            return v;
        }
    }
};
