    double y_mid = (node-&gt;bounds.y_min + node-&gt;bounds.y_max) / 2;

    int quadrant = 0;
    if (point.x &gt;= x_mid) quadrant += 1;
    if (point.y &gt;= y_mid) quadrant += 2;

    // 递归插入到子节点
    insertQuad(node-&gt;children[quadrant], point);
