    if (key &lt;= root-&gt;key) {
        root-&gt;left = insertTreap(root-&gt;left, key);

        // 检查堆性质，若违反则右旋
        if (root-&gt;left-&gt;priority &lt; root-&gt;priority) {
            root = rotateRight(root);
        }
    } else {
