        if (!root) {
            return std::make_unique&lt;Node&gt;(key);
        }

        if (key &lt;= root-&gt;key) {
            root-&gt;left = insert(std::move(root-&gt;left), key);
            if (root-&gt;left-&gt;priority &lt; root-&gt;priority) {
                root = rotateRight(std::move(root));
