C++<pre><code>class SplayTree {
private:
    struct Node {
        int key;
        Node *left, *right, *parent;
        Node(int k) : key(k), left(nullptr), right(nullptr), parent(nullptr) {}
    };

    Node *root;

    void rotate(Node *x) {
        Node *p = x-&gt;parent;
        Node *g = p-&gt;parent;

        if (p-&gt;left == x) {
            p-&gt;left = x-&gt;right;
            if (x-&gt;right) x-&gt;right-&gt;parent = p;
            x-&gt;right = p;
        } else {
            p-&gt;right = x-&gt;left;
            if (x-&gt;left) x-&gt;left-&gt;parent = p;
            x-&gt;left = p;
        }

        p-&gt;parent = x;
        x-&gt;parent = g;

        if (g) {
            if (g-&gt;left == p) g-&gt;left = x;
            else g-&gt;right = x;
        } else {
            root = x;
        }
    }

    void splay(Node *x) {
        while (x-&gt;parent) {
            Node *p = x-&gt;parent;
            Node *g = p-&gt;parent;

            if (!g) {
                rotate(x);
            } else if ((g-&gt;left == p) == (p-&gt;left == x)) {
                // 同侧：Zig-Zig
                rotate(p);
                rotate(x);
            } else {
                // 异侧：Zig-Zag
                rotate(x);
                rotate(x);
            }
        }
    }

public:
    SplayTree() : root(nullptr) {}

    bool search(int key) {
        Node *curr = root;
        Node *prev = nullptr;

        while (curr &amp;&amp; curr-&gt;key != key) {
            prev = curr;
            curr = (key &lt; curr-&gt;key) ? curr-&gt;left : curr-&gt;right;
        }

        if (curr) {
            splay(curr);
            return true;
        }
        if (prev) splay(prev);
        return false;
    }

    void insert(int key) {
        if (!root) {
            root = new Node(key);
            return;
        }

        Node *curr = root;
        Node *prev = nullptr;

        while (curr) {
            prev = curr;
            curr = (key &lt; curr-&gt;key) ? curr-&gt;left : curr-&gt;right;
        }

        Node *newNode = new Node(key);
        newNode-&gt;parent = prev;

        if (key &lt; prev-&gt;key) prev-&gt;left = newNode;
        else prev-&gt;right = newNode;

        splay(newNode);
    }
};
</code></pre>

