C<pre><code>int* buildSuffixArrayDC3(char *text, int n) {
    int *sa = (int*)malloc(sizeof(int) * n);
    int *rank = (int*)malloc(sizeof(int) * 2 * n);
    int *tmp = (int*)malloc(sizeof(int) * n);

    // 初始排名：按字符值
    for (int i = 0; i &lt; n; i++) {
        sa[i] = i;
        rank[i] = (unsigned char)text[i];
    }

    // 倍增排序
    for (int k = 1; k &lt; n; k *= 2) {
        // 按二元组 (rank[i], rank[i+k]) 排序
        for (int i = 0; i &lt; n - 1; i++) {
            for (int j = 0; j &lt; n - i - 1; j++) {
                int a = sa[j], b = sa[j + 1];
                int ra = rank[a], rb = rank[b];
                int rak = (a + k &lt; n) ? rank[a + k] : -1;
                int rbk = (b + k &lt; n) ? rank[b + k] : -1;

                if (ra &gt; rb || (ra == rb &amp;&amp; rak &gt; rbk)) {
                    int temp = sa[j];
                    sa[j] = sa[j + 1];
                    sa[j + 1] = temp;
                }
            }
        }

        // 重新计算排名
        tmp[sa[0]] = 0;
        for (int i = 1; i &lt; n; i++) {
            int a = sa[i - 1], b = sa[i];
            int ra = rank[a], rb = rank[b];
            int rak = (a + k &lt; n) ? rank[a + k] : -1;
            int rbk = (b + k &lt; n) ? rank[b + k] : -1;

            tmp[b] = tmp[a] + (ra != rb || rak != rbk);
        }

        for (int i = 0; i &lt; n; i++) {
            rank[i] = tmp[i];
        }

        // 所有排名不同，排序完成
        if (rank[sa[n - 1]] == n - 1) break;
    }

    free(rank);
    free(tmp);
    return sa;
}
