C++<pre><code>#include &lt;vector&gt;
#include &lt;string&gt;
#include &lt;algorithm&gt;

class SuffixArray {
private:
    std::string text;
    std::vector&lt;int&gt; sa;
    std::vector&lt;int&gt; lcp;
    std::vector&lt;int&gt; rank;
    int n;

public:
    SuffixArray(const std::string&amp; s) : text(s), n(s.length()) {
        sa.resize(n);
        lcp.resize(n);
        rank.resize(n);
        buildSA();
        buildLCP();
    }

    void buildSA() {
        for (int i = 0; i &lt; n; i++) sa[i] = i;
        for (int i = 0; i &lt; n; i++) rank[i] = text[i];

        std::vector&lt;int&gt; tmp(n);
        for (int k = 1; k &lt; n; k *= 2) {
            auto cmp = [&amp;](int a, int b) {
                if (rank[a] != rank[b]) return rank[a] &lt; rank[b];
                int ra = (a + k &lt; n) ? rank[a + k] : -1;
                int rb = (b + k &lt; n) ? rank[b + k] : -1;
                return ra &lt; rb;
            };

            std::sort(sa.begin(), sa.end(), cmp);

            tmp[sa[0]] = 0;
            for (int i = 1; i &lt; n; i++) {
                tmp[sa[i]] = tmp[sa[i - 1]] + (cmp(sa[i - 1], sa[i]) ? 1 : 0);
            }
            rank = tmp;

            if (rank[sa[n - 1]] == n - 1) break;
        }
    }

    void buildLCP() {
        for (int i = 0; i &lt; n; i++) rank[sa[i]] = i;

        int h = 0;
        for (int i = 0; i &lt; n; i++) {
            if (rank[i] &gt; 0) {
                int j = sa[rank[i] - 1];
                while (i + h &lt; n &amp;&amp; j + h &lt; n &amp;&amp; text[i + h] == text[j + h]) h++;
                lcp[rank[i]] = h;
                if (h &gt; 0) h--;
            }
        }
    }

    int countOccurrences(const std::string&amp; pattern) {
        int m = pattern.length();

        int left = 0, right = n;
        while (left &lt; right) {
            int mid = (left + right) / 2;
            if (text.compare(sa[mid], m, pattern) &lt; 0) left = mid + 1;
            else right = mid;
        }
        int start = left;

        right = n;
        while (left &lt; right) {
            int mid = (left + right) / 2;
            if (text.compare(sa[mid], m, pattern) &lt;= 0) left = mid + 1;
            else right = mid;
        }

        return right - start;
    }

    // 最长重复子串
    std::string longestRepeatedSubstring() {
        int maxLen = 0, maxIdx = 0;
        for (int i = 1; i &lt; n; i++) {
            if (lcp[i] &gt; maxLen) {
                maxLen = lcp[i];
                maxIdx = sa[i];
            }
        }
        return text.substr(maxIdx, maxLen);
    }
};
