C++<pre><code>#include &lt;vector&gt;
#include &lt;stack&gt;
#include &lt;algorithm&gt;

class CartesianTree {
private:
    struct Node {
        int key, value;
        Node *left, *right, *parent;
        Node(int k, int v) : key(k), value(v), 
                            left(nullptr), right(nullptr), parent(nullptr) {}
    };

    Node *root;

public:
    CartesianTree() : root(nullptr) {}

    void build(const std::vector&lt;int&gt;&amp; keys, const std::vector&lt;int&gt;&amp; values) {
        int n = keys.size();
        if (n == 0) return;

        std::stack&lt;Node*&gt; st;

        for (int i = 0; i &lt; n; i++) {
            Node *node = new Node(keys[i], values[i]);
            Node *last = nullptr;

            while (!st.empty() &amp;&amp; st.top()-&gt;value &gt; values[i]) {
                last = st.top();
                st.pop();
            }

            node-&gt;left = last;
            if (last) last-&gt;parent = node;

            if (!st.empty()) {
                st.top()-&gt;right = node;
                node-&gt;parent = st.top();
            }

            st.push(node);
        }

        root = st.top();
        while (root-&gt;parent) root = root-&gt;parent;
    }

    int rmq(int l, int r) {
        Node *curr = root;

        while (curr) {
            if (curr-&gt;key &lt; l) {
                curr = curr-&gt;right;
            } else if (curr-&gt;key &gt; r) {
                curr = curr-&gt;left;
            } else {
                return curr-&gt;value;
            }
        }

        return INT_MAX;
    }

    std::vector&lt;int&gt; inorder() {
        std::vector&lt;int&gt; result;
        inorderHelper(root, result);
        return result;
    }

private:
    void inorderHelper(Node *node, std::vector&lt;int&gt;&amp; result) {
        if (!node) return;
        inorderHelper(node-&gt;left, result);
        result.push_back(node-&gt;value);
        inorderHelper(node-&gt;right, result);
    }
};
