        KVPair *p1 = getKVPair(t1, i);
        KVPair *p2 = getKVPair(t2, j);

        int cmp = strcmp(p1-&gt;key, p2-&gt;key);

        if (cmp &lt; 0) {
            addKVPair(result, p1);
            i++;
        } else if (cmp &gt; 0) {
            addKVPair(result, p2);
            j++;
