        (*heap)-&gt;head = min-&gt;sibling;
    } else {
        minPrev-&gt;sibling = min-&gt;sibling;
    }

    BinomialHeap *childHeap = reverseList(min-&gt;child);
    *heap = unionBinomialHeaps(*heap, childHeap);

    int minValue = min-&gt;value;
    free(min);
    free(childHeap);

    return minValue;
}
