C<pre><code>FibonacciHeap* unionFibonacci(FibonacciHeap *h1, FibonacciHeap *h2) {
    FibonacciHeap *heap = createFibonacciHeap();

    if (h1-&gt;min == NULL) {
        heap-&gt;min = h2-&gt;min;
    } else if (h2-&gt;min == NULL) {
        heap-&gt;min = h1-&gt;min;
    } else {
        FibonacciNode *temp = h1-&gt;min-&gt;right;
        h1-&gt;min-&gt;right = h2-&gt;min-&gt;right;
        h2-&gt;min-&gt;right-&gt;left = h1-&gt;min;
        h2-&gt;min-&gt;right = temp;
        temp-&gt;left = h2-&gt;min;

        heap-&gt;min = (h1-&gt;min-&gt;key &lt; h2-&gt;min-&gt;key) ? h1-&gt;min : h2-&gt;min;
    }

    heap-&gt;n = h1-&gt;n + h2-&gt;n;

    free(h1);
    free(h2);

    return heap;
}
