void bubbleSort(int arr[], int n) {
    // 外层循环：控制趟数，共 n-1 趟
    for (int i = 0; i &lt; n - 1; i++) {
        // 内层循环：每趟比较次数递减
        for (int j = 0; j &lt; n - 1 - i; j++) {
            // 如果前一个元素大于后一个元素，交换
            if (arr[j] &gt; arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
