int findKthLargest(int arr[], int n, int k) {
    // 执行k趟，每趟把当前最大的移到右边
    for (int i = 0; i &lt; k; i++) {
        for (int j = 0; j &lt; n - 1 - i; j++) {
            if (arr[j] &gt; arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
    // 第K大元素在位置 n-k
