C<pre><code>// 大规模数据时减少比较次数
void optimizedInsertionSort(int arr[], int n) {
    for (int i = 1; i &lt; n; i++) {
        int key = arr[i];

        // 二分查找（比较次数 O(log i)）
        int left = 0, right = i - 1;
        while (left &lt;= right) {
            int mid = left + (right - left) / 2;
            if (arr[mid] &lt;= key) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        // 移动元素（移动次数不变，仍为 O(i)）
        for (int j = i - 1; j &gt;= left; j--) {
            arr[j + 1] = arr[j];
        }
        arr[left] = key;
    }
}
