    // 构建大根堆
    for (int i = n / 2 - 1; i &gt;= 0; i--) {
        heapify(arr, n, i);
    }

    // 执行 k-1 次取出堆顶
    for (int i = n - 1; i &gt; n - k; i--) {
        int temp = arr[0];
        arr[0] = arr[i];
        arr[i] = temp;
        heapify(arr, i, 0);
    }

    // 堆顶就是第 K 大元素
    return arr[0];
}

