typedef struct Node {
    double value;
    struct Node *next;
} Node;

void bucketSort(double arr[], int n) {
    // 创建n个桶
    Node **buckets = (Node**)calloc(n, sizeof(Node*));

    // 分配元素到桶
    for (int i = 0; i &lt; n; i++) {
        int index = (int)(n * arr[i]);  // 映射到桶

        // 插入到链表头部
        Node *newNode = (Node*)malloc(sizeof(Node));
        newNode-&gt;value = arr[i];
        newNode-&gt;next = buckets[index];
        buckets[index] = newNode;
    }

    // 对每个桶排序（插入排序）
    for (int i = 0; i &lt; n; i++) {
        Node *curr = buckets[i];
        while (curr) {
            Node *next = curr-&gt;next;
            while (next) {
                if (curr-&gt;value &gt; next-&gt;value) {
                    double temp = curr-&gt;value;
                    curr-&gt;value = next-&gt;value;
                    next-&gt;value = temp;
                }
                next = next-&gt;next;
            }
            curr = curr-&gt;next;
        }
    }

    // 合并所有桶
    int index = 0;
    for (int i = 0; i &lt; n; i++) {
        Node *curr = buckets[i];
        while (curr) {
            arr[index++] = curr-&gt;value;
            Node *temp = curr;
            curr = curr-&gt;next;
            free(temp);
        }
    }

    free(buckets);
}
