C<pre><code>// Sedgewick序列生成
void generateSedgewick(int gaps[], int *count, int n) {
    int k = 0;
    *count = 0;

    while (1) {
        int gap;
        if (k % 2 == 0) {
            gap = 9 * (1 &lt;&lt; k) - 9 * (1 &lt;&lt; (k / 2)) + 1;
        } else {
            gap = 8 * (1 &lt;&lt; k) - 6 * (1 &lt;&lt; ((k + 1) / 2)) + 1;
        }

        if (gap &gt; n) break;
        gaps[(*count)++] = gap;
        k++;
    }
}

void shellSortSedgewick(int arr[], int n) {
    int gaps[100];
    int count;
    generateSedgewick(gaps, &amp;count, n);

    // 从大到小使用gap
    for (int i = count - 1; i &gt;= 0; i--) {
        int gap = gaps[i];

        for (int j = gap; j &lt; n; j++) {
            int temp = arr[j];
            int k;

            for (k = j; k &gt;= gap &amp;&amp; arr[k - gap] &gt; temp; k -= gap) {
                arr[k] = arr[k - gap];
            }

            arr[k] = temp;
        }
    }
}
