C<pre><code>void cocktailSortWithExit(int arr[], int n) {
    int left = 0;
    int right = n - 1;

    while (left &lt; right) {
        int lastSwap = left;
        int swapped = 0;

        // 从左到右
        for (int i = left; i &lt; right; i++) {
            if (arr[i] &gt; arr[i + 1]) {
                int temp = arr[i];
                arr[i] = arr[i + 1];
                arr[i + 1] = temp;
                lastSwap = i;
                swapped = 1;
            }
        }
        right = lastSwap;

        if (!swapped) break;  // 提前退出

        swapped = 0;
        lastSwap = right;

        // 从右到左
        for (int i = right; i &gt; left; i--) {
            if (arr[i] &lt; arr[i - 1]) {
                int temp = arr[i];
                arr[i] = arr[i - 1];
                arr[i - 1] = temp;
                lastSwap = i;
                swapped = 1;
            }
        }
        left = lastSwap;

        if (!swapped) break;  // 提前退出
    }
}
