double findRoot(double (*f)(double), double a, double b, double epsilon) {
    while (b - a &gt; epsilon) {
        double fa = f(a), fb = f(b);

        // 线性插值估计零点位置
        double c = a - fa * (b - a) / (fb - fa);

        double fc = f(c);

        if (fabs(fc) &lt; epsilon) return c;

        if (fa * fc &lt; 0) b = c;
        else a = c;
    }

    return (a + b) / 2;
}
