    for (int i = 0; i &lt; vertex_count_; i++) {
        std::cout &lt;&lt; vertices_[i] &lt;&lt; " ";
        for (int j = 0; j &lt; vertex_count_; j++) {
            if (matrix_[i][j] == no_edge_value_) {
