// Dijkstra 算法
void dijkstra(int graph[V][V], int src) {
    int dist[V];       // 最短距离数组
    int visited[V];    // 访问标记
    int parent[V];     // 路径前驱

    // 初始化
    for (int i = 0; i &lt; V; i++) {
        dist[i] = INF;
        visited[i] = 0;
        parent[i] = -1;
    }
    dist[src] = 0;

    printf("Dijkstra 算法执行过程:\n\n");

    // 对所有顶点执行
    for (int count = 0; count &lt; V - 1; count++) {
        // 选择未访问中距离最小的顶点
        int u = minDistance(dist, visited);
        if (u == -1) break;  // 无法到达的顶点

        visited[u] = 1;
        printf("选择顶点 %c, 距离=%d\n", 'A' + u, dist[u]);

        // 松弛所有邻居
        for (int v = 0; v &lt; V; v++) {
            if (!visited[v] &amp;&amp; graph[u][v] != INF &amp;&amp; 
                dist[u] != INF &amp;&amp; 
                dist[u] + graph[u][v] &lt; dist[v]) {

                dist[v] = dist[u] + graph[u][v];
                parent[v] = u;
                printf("  松弛 %c: dist[%c] = %d\n", 
                       'A' + v, 'A' + v, dist[v]);
            }
        }
        printf("\n");
    }

    // 打印结果
    printf("\n最短路径结果:\n");
    printf("目标\t距离\t路径\n");
    for (int i = 0; i &lt; V; i++) {
        printf("%c\t", 'A' + i);
        if (dist[i] == INF) {
            printf("不可达\t-\n");
        } else {
