#define V 4
#define E 4
#define INF INT_MAX

typedef struct {
    int src, dest, weight;
} Edge;

void bellmanFord(Edge edges[], int src) {
    int dist[V];
    int parent[V];

    // 初始化
    for (int i = 0; i &lt; V; i++) {
        dist[i] = INF;
        parent[i] = -1;
    }
    dist[src] = 0;

    printf("Bellman-Ford 算法执行:\n\n");

    // V-1 轮松弛
    for (int i = 1; i &lt; V; i++) {
        printf("第 %d 轮松弛:\n", i);
        int updated = 0;

        for (int j = 0; j &lt; E; j++) {
            int u = edges[j].src;
            int v = edges[j].dest;
            int w = edges[j].weight;

            if (dist[u] != INF &amp;&amp; dist[u] + w &lt; dist[v]) {
                dist[v] = dist[u] + w;
                parent[v] = u;
                updated = 1;
                printf("  边(%c,%c): dist[%c] = %d\n", 
                       'A' + u, 'A' + v, 'A' + v, dist[v]);
            }
        }

        if (!updated) {
            printf("  无更新，提前终止\n");
            break;
        }
    }

    // 检查负权回路
    printf("\n检查负权回路:\n");
    int hasNegativeCycle = 0;
    for (int j = 0; j &lt; E; j++) {
        int u = edges[j].src;
        int v = edges[j].dest;
        int w = edges[j].weight;

