void floydWarshall(int dist[V][V]) {
    int next[V][V];  // 用于路径重建

    // 初始化 next 数组
    for (int i = 0; i &lt; V; i++) {
        for (int j = 0; j &lt; V; j++) {
            if (dist[i][j] != INF &amp;&amp; i != j) {
                next[i][j] = j;
            } else {
                next[i][j] = -1;
            }
        }
    }

    printf("Floyd-Warshall 算法执行:\n\n");

    // 三重循环
    for (int k = 0; k &lt; V; k++) {
        printf("k = %d:\n", k);

        for (int i = 0; i &lt; V; i++) {
            for (int j = 0; j &lt; V; j++) {
                if (dist[i][k] != INF &amp;&amp; dist[k][j] != INF &amp;&amp;
                    dist[i][k] + dist[k][j] &lt; dist[i][j]) {

                    dist[i][j] = dist[i][k] + dist[k][j];
                    next[i][j] = next[i][k];

                    printf("  dist[%d][%d] = %d\n", i, j, dist[i][j]);
                }
            }
        }
    }

    // 打印最终距离矩阵
    printf("\n最终距离矩阵:\n");
    printf("     ");
    for (int i = 0; i &lt; V; i++) printf("%4d ", i);
    printf("\n");

    for (int i = 0; i &lt; V; i++) {
        printf("%4d ", i);
        for (int j = 0; j &lt; V; j++) {
            if (dist[i][j] == INF) printf("  INF ");
            else printf("%5d ", dist[i][j]);
        }
        printf("\n");
    }

    // 检测负权回路
    printf("\n检测负权回路:\n");
    int hasNegativeCycle = 0;
    for (int i = 0; i &lt; V; i++) {
        if (dist[i][i] &lt; 0) {
            printf("顶点 %d 存在负权回路\n", i);
