// 找到 key 值最小且未包含在 MST 中的顶点
int minKey(int key[], int mstSet[]) {
    int min = INF, minIndex = -1;

    for (int v = 0; v &lt; V; v++) {
        if (!mstSet[v] &amp;&amp; key[v] &lt; min) {
            min = key[v];
            minIndex = v;
        }
    }

    return minIndex;
}

// 打印 MST
void printMST(int parent[], int graph[V][V]) {
    printf("边\t\t权值\n");
    int totalWeight = 0;
    for (int i = 1; i &lt; V; i++) {
        printf("%c - %c\t\t%d\n", 
               'A' + parent[i], 'A' + i, graph[i][parent[i]]);
        totalWeight += graph[i][parent[i]];
    }
    printf("总权值: %d\n", totalWeight);
}

// Prim 算法
void primMST(int graph[V][V]) {
    int parent[V];   // MST 中各顶点的父节点
    int key[V];      // 连接到 MST 的最小权值
    int mstSet[V];   // 是否已加入 MST

    // 初始化
    for (int i = 0; i &lt; V; i++) {
        key[i] = INF;
        mstSet[i] = 0;
        parent[i] = -1;
    }

    // 从顶点 0 开始
    key[0] = 0;
    parent[0] = -1;  // 第一个顶点是根

    printf("Prim 算法执行过程:\n\n");

    // 构建 MST
    for (int count = 0; count &lt; V - 1; count++) {
        // 选择 key 最小的未选顶点
        int u = minKey(key, mstSet);
        mstSet[u] = 1;

        printf("步骤 %d: 选择顶点 %c\n", count + 1, 'A' + u);
        if (parent[u] != -1) {
            printf("  加入边: (%c, %c), 权值=%d\n", 
                   'A' + parent[u], 'A' + u, key[u]);
        }

        // 更新相邻顶点的 key 值
        for (int v = 0; v &lt; V; v++) {
            if (graph[u][v] &amp;&amp; !mstSet[v] &amp;&amp; graph[u][v] &lt; key[v]) {
                parent[v] = u;
                key[v] = graph[u][v];
                printf("  更新 key[%c] = %d\n", 'A' + v, key[v]);
            }
        }
        printf("\n");
    }

    printf("\n最小生成树:\n");
    printMST(parent, graph);
}

