C<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

#define V 4

typedef struct {
    int src, dest, weight;
} Edge;

// 并查集
int parent[V];
int rank[V];

// 初始化并查集
void initUnionFind() {
    for (int i = 0; i &lt; V; i++) {
        parent[i] = i;
        rank[i] = 0;
    }
}

// 查找（带路径压缩）
int find(int i) {
    if (parent[i] != i) {
        parent[i] = find(parent[i]);  // 路径压缩
    }
    return parent[i];
}

// 合并（按秩合并）
int unionSets(int i, int j) {
    int rootI = find(i);
    int rootJ = find(j);

    if (rootI == rootJ) {
        return 0;  // 已经在同一集合
    }

    // 按秩合并
    if (rank[rootI] &lt; rank[rootJ]) {
        parent[rootI] = rootJ;
    } else if (rank[rootI] &gt; rank[rootJ]) {
        parent[rootJ] = rootI;
    } else {
        parent[rootJ] = rootI;
        rank[rootI]++;
    }

    return 1;  // 合并成功
}

// 边比较函数（用于排序）
int compareEdges(const void *a, const void *b) {
    return ((Edge*)a)-&gt;weight - ((Edge*)b)-&gt;weight;
}

// Kruskal 算法
void kruskalMST(Edge edges[], int E) {
    // 按权值排序边
    qsort(edges, E, sizeof(Edge), compareEdges);

    printf("排序后的边:\n");
    for (int i = 0; i &lt; E; i++) {
        printf("%d. (%c,%c) = %d\n", i + 1, 
               'A' + edges[i].src, 'A' + edges[i].dest, 
               edges[i].weight);
    }
    printf("\n");

    initUnionFind();

    Edge result[V - 1];
    int e = 0;  // 已选边数
    int i = 0;  // 当前检查的边索引

    printf("Kruskal 算法执行过程:\n\n");

    while (e &lt; V - 1 &amp;&amp; i &lt; E) {
        Edge next = edges[i++];

        printf("检查边 (%c,%c) = %d\n", 
               'A' + next.src, 'A' + next.dest, next.weight);

        int rootSrc = find(next.src);
        int rootDest = find(next.dest);

        if (rootSrc != rootDest) {
            // 不形成环，接受该边
            result[e++] = next;
            unionSets(next.src, next.dest);
            printf("  接受！合并集合\n");

            printf("  当前集合: ");
            for (int j = 0; j &lt; V; j++) {
                printf("{");
                for (int k = 0; k &lt; V; k++) {
                    if (find(k) == j) printf("%c ", 'A' + k);
                }
                printf("} ");
            }
            printf("\n\n");
        } else {
            printf("  拒绝！会形成环\n\n");
        }
    }

    // 输出结果
    printf("最小生成树:\n");
    printf("边\t\t权值\n");
    int totalWeight = 0;
    for (i = 0; i &lt; e; i++) {
        printf("(%c,%c)\t\t%d\n", 
               'A' + result[i].src, 'A' + result[i].dest, 
               result[i].weight);
        totalWeight += result[i].weight;
    }
    printf("总权值: %d\n", totalWeight);
}

int main() {
    // 边列表
    Edge edges[] = {
        {0, 1, 4},  // A-B
        {0, 2, 2},  // A-C
        {0, 3, 3},  // A-D
        {1, 3, 1},  // B-D
        {2, 3, 6}   // C-D
    };
    int E = sizeof(edges) / sizeof(edges[0]);

    kruskalMST(edges, E);

    return 0;
}
