#define MAX_V 100

int* topologicalSortKahn(int graph[MAX_V][MAX_V], int n, int *returnSize) {
    // 计算入度
    int *inDegree = (int*)calloc(n, sizeof(int));

    printf("计算入度:\n");
    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; n; j++) {
            if (graph[i][j]) {
                inDegree[j]++;
            }
        }
    }

    for (int i = 0; i &lt; n; i++) {
        printf("  顶点 %c: 入度 = %d\n", 'A' + i, inDegree[i]);
    }
    printf("\n");

    // 初始化队列（入度为0的顶点）
    int *queue = (int*)malloc(sizeof(int) * n);
    int front = 0, rear = 0;

    for (int i = 0; i &lt; n; i++) {
        if (inDegree[i] == 0) {
            queue[rear++] = i;
            printf("顶点 %c 入度=0，入队\n", 'A' + i);
        }
    }
    printf("\n");

    // 拓扑排序
    int *result = (int*)malloc(sizeof(int) * n);
    int count = 0;

    printf("Kahn 算法执行:\n");

    while (front &lt; rear) {
        int v = queue[front++];
        result[count++] = v;
        printf("步骤 %d: 输出 %c\n", count, 'A' + v);

        // 更新邻居的入度
        for (int i = 0; i &lt; n; i++) {
            if (graph[v][i]) {
                inDegree[i]--;
                printf("  邻居 %c 入度: %d → %d", 'A' + i, inDegree[i] + 1, inDegree[i]);

                if (inDegree[i] == 0) {
                    queue[rear++] = i;
                    printf(", 入队");
                }
                printf("\n");
            }
        }
    }

    free(inDegree);
    free(queue);

    // 检查是否有环
    if (count != n) {
        printf("\n检测到环！只输出了 %d/%d 个顶点\n", count, n);
        free(result);
        *returnSize = 0;
        return NULL;
    }

    printf("\n拓扑排序结果: ");
    for (int i = 0; i &lt; n; i++) {
        printf("%c ", 'A' + result[i]);
    }
    printf("\n");

    *returnSize = n;
    return result;
}

int main() {
    // 示例图
    int n = 5;
    int graph[MAX_V][MAX_V] = {0};

    // 添加边: A→B, A→C, B→D, B→E
    graph[0][1] = 1;  // A → B
    graph[0][2] = 1;  // A → C
    graph[1][3] = 1;  // B → D
    graph[1][4] = 1;  // B → E

    printf("图的边:\n");
    printf("  A → B\n  A → C\n  B → D\n  B → E\n\n");

