    if (hasCycle) return;

    visited[v] = 1;
    inStack[v] = 1;

    printf("  进入 %c\n", 'A' + v);

    for (int i = 0; i &lt; n; i++) {
        if (graph[v][i]) {
            if (!visited[i]) {
                dfsTopo(graph, i, n);
            } else if (inStack[i]) {
                // 发现回边，存在环
                printf("  检测到环: %c → %c 形成回边\n", 'A' + v, 'A' + i);
                hasCycle = 1;
                return;
            }
        }
    }

    inStack[v] = 0;
    result[resultIndex++] = v;
    printf("  完成 %c, 加入结果\n", 'A' + v);
}

