    resultIndex = 0;
    hasCycle = 0;

    printf("DFS 拓扑排序:\n");

    for (int i = 0; i &lt; n; i++) {
        if (!visited[i]) {
            printf("DFS 从 %c 开始:\n", 'A' + i);
            dfsTopo(graph, i, n);
