        printf("%c ", 'A' + result[i]);
    }
    printf("\n");

    printf("拓扑排序: ");
    for (int i = 0; i &lt; n; i++) {
        printf("%c ", 'A' + topoOrder[i]);
    }
    printf("\n");

    *returnSize = n;
