学习顺序: 先学 0，再学 1 和 2（顺序可换），最后学 3
</code></pre> C<pre><code>int canFinish(int numCourses, int prerequisites[][2], int prerequisitesSize) {
    int **graph = (int**)malloc(sizeof(int*) * numCourses);
    int *inDegree = (int*)calloc(numCourses, sizeof(int));

    for (int i = 0; i &lt; numCourses; i++) {
        graph[i] = (int*)calloc(numCourses, sizeof(int));
    }

    // 建图: prerequisites[i] = [course, prereq]
    for (int i = 0; i &lt; prerequisitesSize; i++) {
        int course = prerequisites[i][0];
        int prereq = prerequisites[i][1];
        graph[prereq][course] = 1;
        inDegree[course]++;
    }

    // Kahn 算法
    int *queue = (int*)malloc(sizeof(int) * numCourses);
    int front = 0, rear = 0;

    for (int i = 0; i &lt; numCourses; i++) {
        if (inDegree[i] == 0) {
            queue[rear++] = i;
        }
    }

    int count = 0;
    while (front &lt; rear) {
        int v = queue[front++];
        count++;

        for (int i = 0; i &lt; numCourses; i++) {
            if (graph[v][i]) {
                inDegree[i]--;
                if (inDegree[i] == 0) {
                    queue[rear++] = i;
                }
            }
        }
    }

    // 释放内存
    for (int i = 0; i &lt; numCourses; i++) free(graph[i]);
    free(graph);
    free(inDegree);
    free(queue);

    return count == numCourses;
