C<pre><code>void criticalPath(int graph[MAX_V][MAX_V], int n, int weights[MAX_V][MAX_V]) {
    int returnSize;
    int *topoOrder = topologicalSortKahn(graph, n, &amp;returnSize);

    if (topoOrder == NULL) {
        printf("图中有环，无法计算关键路径\n");
        return;
    }

    // 计算最早发生时间
    int *earliest = (int*)calloc(n, sizeof(int));

    for (int i = 0; i &lt; n; i++) {
        int v = topoOrder[i];
        for (int j = 0; j &lt; n; j++) {
            if (graph[j][v]) {
                int finish = earliest[j] + weights[j][v];
                if (finish &gt; earliest[v]) {
                    earliest[v] = finish;
                }
            }
        }
    }

    // 计算最晚发生时间
    int *latest = (int*)malloc(sizeof(int) * n);
    for (int i = 0; i &lt; n; i++) {
        latest[i] = earliest[topoOrder[n - 1]];
    }

    for (int i = n - 1; i &gt;= 0; i--) {
        int v = topoOrder[i];
        for (int j = 0; j &lt; n; j++) {
            if (graph[v][j]) {
                int start = latest[j] - weights[v][j];
                if (start &lt; latest[v]) {
                    latest[v] = start;
                }
            }
        }
    }

    // 输出关键活动
    printf("关键活动（松弛时间为0）:\n");
    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; n; j++) {
            if (graph[i][j]) {
                int e = earliest[i];
                int l = latest[j] - weights[i][j];
                if (e == l) {
                    printf("  %c → %c (权值=%d)\n", 
                           'A' + i, 'A' + j, weights[i][j]);
                }
            }
        }
    }

    free(earliest);
    free(latest);
    free(topoOrder);
}
