C<pre><code>// 使用回溯法生成所有拓扑排序
void allTopologicalSorts(int graph[MAX_V][MAX_V], int n, 
                         int *result, int count, 
                         int *inDegree, int *visited) {
    if (count == n) {
        // 输出一个排序
        for (int i = 0; i &lt; n; i++) {
            printf("%c ", 'A' + result[i]);
        }
        printf("\n");
        return;
    }

    for (int i = 0; i &lt; n; i++) {
        if (!visited[i] &amp;&amp; inDegree[i] == 0) {
            // 选择顶点 i
            result[count] = i;
            visited[i] = 1;

            // 更新入度
            int temp[MAX_V];
            for (int j = 0; j &lt; n; j++) {
                temp[j] = inDegree[j];
                if (graph[i][j]) {
                    inDegree[j]--;
                }
            }

            // 递归
            allTopologicalSorts(graph, n, result, count + 1, inDegree, visited);

            // 回溯
            visited[i] = 0;
            for (int j = 0; j &lt; n; j++) {
                inDegree[j] = temp[j];
            }
        }
    }
}
