C<pre><code>// 使用最小堆（优先队列）替代普通队列
int* topologicalSortLexicographically(int graph[MAX_V][MAX_V], int n, int *returnSize) {
    int *inDegree = (int*)calloc(n, sizeof(int));

    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; n; j++) {
            if (graph[i][j]) {
                inDegree[j]++;
            }
        }
    }

    // 使用最小堆（这里简化实现）
    int *result = (int*)malloc(sizeof(int) * n);
    int count = 0;

    while (count &lt; n) {
        // 找入度为0的最小顶点
        int min = -1;
        for (int i = 0; i &lt; n; i++) {
            if (inDegree[i] == 0) {
                if (min == -1 || i &lt; min) {
                    min = i;
                }
            }
        }

        if (min == -1) {
            free(result);
            *returnSize = 0;
            return NULL;
        }

        result[count++] = min;
        inDegree[min] = -1;  // 标记已处理

        for (int i = 0; i &lt; n; i++) {
            if (graph[min][i]) {
                inDegree[i]--;
            }
        }
    }

    *returnSize = n;
    return result;
}
