C<pre><code>#define INF 1000000000

int lx[MAX_V], ly[MAX_V];  // 顶点标号
int slack[MAX_V];          // 松弛量

int dfsKM(int graph[MAX_V][MAX_V], int u, int n) {
    visited[u] = 1;

    for (int v = 0; v &lt; n; v++) {
        if (!visited[v]) {
            int t = lx[u] + ly[v] - graph[u][v];

            if (t == 0) {
                visited[v] = 1;
                if (match[v] == -1 || dfsKM(graph, match[v], n)) {
                    match[v] = u;
                    return 1;
                }
            } else if (slack[v] &gt; t) {
                slack[v] = t;
            }
        }
    }
    return 0;
}

int maxWeightMatching(int graph[MAX_V][MAX_V], int n) {
    // 初始化标号
    for (int i = 0; i &lt; n; i++) {
        lx[i] = -INF;
        ly[i] = 0;
        match[i] = -1;

        for (int j = 0; j &lt; n; j++) {
            if (graph[i][j] &gt; lx[i]) {
                lx[i] = graph[i][j];
            }
        }
    }

    // KM算法主循环
    for (int u = 0; u &lt; n; u++) {
        for (int i = 0; i &lt; n; i++) slack[i] = INF;

        while (1) {
            for (int i = 0; i &lt; n; i++) visited[i] = 0;

            if (dfsKM(graph, u, n)) break;

            // 更新标号
            int d = INF;
            for (int i = 0; i &lt; n; i++) {
                if (!visited[i] &amp;&amp; slack[i] &lt; d) {
                    d = slack[i];
                }
            }

            for (int i = 0; i &lt; n; i++) {
                if (visited[i]) lx[i] -= d;
                if (!visited[i]) ly[i] += d;
            }
        }
    }

    // 计算最大权值
    int result = 0;
    for (int i = 0; i &lt; n; i++) {
        if (match[i] != -1) {
            result += graph[match[i]][i];
        }
    }

    return result;
}
