int visited[MAX_V];

int dfs(int u, int t, int minCap, int n) {
    if (u == t) return minCap;  // 到达汇点

    visited[u] = 1;

    for (int v = 0; v &lt; n; v++) {
        int residual = capacity[u][v] - flow[u][v];

        if (!visited[v] &amp;&amp; residual &gt; 0) {
            int augment = dfs(v, t, 
                             (minCap &lt; residual) ? minCap : residual, n);

            if (augment &gt; 0) {
                flow[u][v] += augment;   // 增加正向流量
                flow[v][u] -= augment;   // 减少反向流量
                return augment;
            }
        }
    }

    return 0;
}

