        for (int j = 0; j &lt; n; j++) {
            flow[i][j] = 0;
        }
    }

    int maxFlow = 0;

    while (1) {
        for (int i = 0; i &lt; n; i++) visited[i] = 0;

        int augment = dfs(s, t, INF, n);

        if (augment == 0) break;  // 无法找到增广路径

        maxFlow += augment;
    }

    return maxFlow;
