    int queue[MAX_V];
    int front = 0, rear = 0;

    queue[rear++] = s;
    visited[s] = 1;
    parent[s] = -1;

    while (front &lt; rear) {
        int u = queue[front++];

        for (int v = 0; v &lt; n; v++) {
            int residual = capacity[u][v] - flow[u][v];

            if (!visited[v] &amp;&amp; residual &gt; 0) {
                visited[v] = 1;
                parent[v] = u;
                queue[rear++] = v;

                if (v == t) return 1;  // 找到增广路径
            }
        }
    }

    return 0;
}

int edmondsKarp(int s, int t, int n) {
    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; n; j++) {
            flow[i][j] = 0;
        }
    }

    int maxFlow = 0;

    while (bfs(s, t, n)) {
        // 找路径上的最小残余容量
        int pathFlow = INF;

        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            int residual = capacity[u][v] - flow[u][v];
            if (residual &lt; pathFlow) pathFlow = residual;
        }

        // 更新流量
        for (int v = t; v != s; v = parent[v]) {
            int u = parent[v];
            flow[u][v] += pathFlow;
            flow[v][u] -= pathFlow;
        }

        maxFlow += pathFlow;
    }

    return maxFlow;
}
