    int maxFlow = 0;

    while (bfsLevel(s, t, n)) {
        int start[MAX_V];
        for (int i = 0; i &lt; n; i++) start[i] = 0;

        while (1) {
            int augment = dfsDinic(s, t, INF, n, start);
            if (augment == 0) break;
            maxFlow += augment;
        }
