// 构造：源点连左部所有点，右部所有点连汇点，边容量为1
int bipartiteMatching(int graph[MAX_V][MAX_V], int n, int m) {
    MaxFlow mf(n + m + 2);
    int s = n + m, t = n + m + 1;

    // 源点连左部
    for (int i = 0; i &lt; n; i++) {
        mf.addEdge(s, i, 1);
    }

    // 左部连右部
    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; m; j++) {
            if (graph[i][j]) {
                mf.addEdge(i, n + j, 1);
            }
        }
    }

    // 右部连汇点
    for (int j = 0; j &lt; m; j++) {
        mf.addEdge(n + j, t, 1);
    }

    return mf.dinic(s, t);
}
