    int stack[MAX_V];
    int stackTop;
    int dfnCount;
    int sccId[MAX_V];
    int sccCount;
} TarjanGraph;

void initTarjan(TarjanGraph *g, int n) {
    g-&gt;vertexCount = n;
    g-&gt;stackTop = 0;
    g-&gt;dfnCount = 0;
    g-&gt;sccCount = 0;

    for (int i = 0; i &lt; n; i++) {
        g-&gt;dfn[i] = -1;
        g-&gt;low[i] = 0;
        g-&gt;visited[i] = 0;
        g-&gt;inStack[i] = 0;
        g-&gt;sccId[i] = -1;
        for (int j = 0; j &lt; n; j++) {
            g-&gt;adj[i][j] = 0;
        }
    }
}

int min(int a, int b) {
    return a &lt; b ? a : b;
}

void tarjanDFS(TarjanGraph *g, int u) {
    g-&gt;dfn[u] = g-&gt;low[u] = g-&gt;dfnCount++;
    g-&gt;stack[g-&gt;stackTop++] = u;
    g-&gt;inStack[u] = 1;

    for (int v = 0; v &lt; g-&gt;vertexCount; v++) {
        if (g-&gt;adj[u][v]) {
            if (g-&gt;dfn[v] == -1) {
                tarjanDFS(g, v);
                g-&gt;low[u] = min(g-&gt;low[u], g-&gt;low[v]);
            } else if (g-&gt;inStack[v]) {
                g-&gt;low[u] = min(g-&gt;low[u], g-&gt;dfn[v]);
            }
        }
    }

    if (g-&gt;dfn[u] == g-&gt;low[u]) {
        int v;
        do {
            v = g-&gt;stack[--g-&gt;stackTop];
            g-&gt;inStack[v] = 0;
            g-&gt;sccId[v] = g-&gt;sccCount;
        } while (v != u);
        g-&gt;sccCount++;
    }
}

void tarjan(TarjanGraph *g) {
    for (int i = 0; i &lt; g-&gt;vertexCount; i++) {
        if (g-&gt;dfn[i] == -1) {
            tarjanDFS(g, i);
        }
    }
}
