    int sccId[MAX_V];
    int sccCount;
    int dfnCount;
} GabowGraph;

void initGabow(GabowGraph *g, int n) {
    g-&gt;vertexCount = n;
    g-&gt;top1 = g-&gt;top2 = 0;
    g-&gt;sccCount = 0;
    g-&gt;dfnCount = 0;

    for (int i = 0; i &lt; n; i++) {
        g-&gt;visited[i] = 0;
        g-&gt;sccId[i] = -1;
        for (int j = 0; j &lt; n; j++) {
            g-&gt;adj[i][j] = 0;
        }
    }
}

void gabowDFS(GabowGraph *g, int u) {
    g-&gt;visited[u] = g-&gt;dfnCount++;
    g-&gt;stack1[g-&gt;top1++] = u;
    g-&gt;stack2[g-&gt;top2++] = u;

    for (int v = 0; v &lt; g-&gt;vertexCount; v++) {
        if (g-&gt;adj[u][v]) {
            if (g-&gt;visited[v] == -1) {
                gabowDFS(g, v);
            } else if (g-&gt;sccId[v] == -1) {
                while (g-&gt;visited[g-&gt;stack2[g-&gt;top2 - 1]] &gt; g-&gt;visited[v]) {
                    g-&gt;top2--;
                }
            }
        }
    }

    if (u == g-&gt;stack2[g-&gt;top2 - 1]) {
        g-&gt;top2--;
        int v;
        do {
            v = g-&gt;stack1[--g-&gt;top1];
            g-&gt;sccId[v] = g-&gt;sccCount;
        } while (v != u);
        g-&gt;sccCount++;
    }
}

void gabow(GabowGraph *g) {
    for (int i = 0; i &lt; g-&gt;vertexCount; i++) {
        g-&gt;visited[i] = -1;
    }

    for (int i = 0; i &lt; g-&gt;vertexCount; i++) {
        if (g-&gt;visited[i] == -1) {
            gabowDFS(g, i);
        }
    }
}
