C++<pre><code>class SCC {
private:
    vector&lt;vector&lt;int&gt;&gt; adj;
    int n;
    vector&lt;int&gt; dfn, low, sccId;
    vector&lt;bool&gt; inStack;
    stack&lt;int&gt; stk;
    int dfnCount, sccCount;

    void tarjan(int u) {
        dfn[u] = low[u] = dfnCount++;
        stk.push(u);
        inStack[u] = true;

        for (int v : adj[u]) {
            if (dfn[v] == -1) {
                tarjan(v);
                low[u] = min(low[u], low[v]);
            } else if (inStack[v]) {
                low[u] = min(low[u], dfn[v]);
            }
        }

        if (dfn[u] == low[u]) {
            int v;
            do {
                v = stk.top();
                stk.pop();
                inStack[v] = false;
                sccId[v] = sccCount;
            } while (v != u);
            sccCount++;
        }
    }

public:
    SCC(int n) : n(n), adj(n), dfn(n, -1), low(n), sccId(n), inStack(n, false), 
                dfnCount(0), sccCount(0) {}

    void addEdge(int u, int v) {
        adj[u].push_back(v);
    }

    vector&lt;vector&lt;int&gt;&gt; findSCC() {
        for (int i = 0; i &lt; n; i++) {
            if (dfn[i] == -1) {
                tarjan(i);
            }
        }

        vector&lt;vector&lt;int&gt;&gt; components(sccCount);
        for (int i = 0; i &lt; n; i++) {
            components[sccId[i]].push_back(i);
        }

        return components;
    }

    int getSCCCount() const { return sccCount; }
    int getSCCId(int v) const { return sccId[v]; }
};
