C<pre><code>int twoSAT(int n, int clauses[][2], int clauseCount) {
    SCC scc(2 * n);

    for (int i = 0; i &lt; clauseCount; i++) {
        int x = clauses[i][0];
        int y = clauses[i][1];

        int nx = (x &gt; 0) ? (x - 1 + n) : (-x - 1);
        int ny = (y &gt; 0) ? (y - 1 + n) : (-y - 1);
        int px = (x &gt; 0) ? (x - 1) : (-x - 1 + n);
        int py = (y &gt; 0) ? (y - 1) : (-y - 1 + n);

        scc.addEdge(nx, py);
        scc.addEdge(ny, px);
    }

    scc.findSCC();

    for (int i = 0; i &lt; n; i++) {
        if (scc.getSCCId(i) == scc.getSCCId(i + n)) {
            return 0;
        }
    }

    return 1;
}
