void addEulerEdge(EulerGraph *g, int u, int v) {
    g-&gt;adj[u][v]++;
    g-&gt;adj[v][u]++;
    g-&gt;degree[u]++;
    g-&gt;degree[v]++;
    g-&gt;edgeCount++;
}

int hasEulerCircuit(EulerGraph *g) {
    for (int i = 0; i &lt; g-&gt;vertexCount; i++) {
        if (g-&gt;degree[i] % 2 != 0) {
            return 0;
        }
    }
    return 1;
}

int hasEulerPath(EulerGraph *g, int *start) {
    int oddCount = 0;
    *start = 0;

    for (int i = 0; i &lt; g-&gt;vertexCount; i++) {
        if (g-&gt;degree[i] % 2 != 0) {
            oddCount++;
            *start = i;
        }
    }

    return oddCount == 0 || oddCount == 2;
}

