int eulerCount = 0;

void hierholzer(EulerGraph *g, int u) {
    for (int v = 0; v &lt; g-&gt;vertexCount; v++) {
        while (g-&gt;adj[u][v] &gt; 0) {
            g-&gt;adj[u][v]--;
            g-&gt;adj[v][u]--;
            hierholzer(g, v);
        }
    }
    eulerPath[eulerCount++] = u;
}

