C<pre><code>int isBridge(EulerGraph *g, int u, int v) {
    EulerGraph temp = *g;

    temp.adj[u][v]--;
    temp.adj[v][u]--;
    temp.degree[u]--;
    temp.degree[v]--;

    int visited1[MAX_V] = {0};
    int count1 = countReachable(&amp;temp, u, visited1);

    *g = temp;
    g-&gt;adj[u][v]++;
    g-&gt;adj[v][u]++;
    g-&gt;degree[u]++;
    g-&gt;degree[v]++;

    int visited2[MAX_V] = {0};
    int count2 = countReachable(g, u, visited2);

    return count1 &lt; count2;
}

void fleury(EulerGraph *g, int u, int path[], int *pathCount) {
    path[(*pathCount)++] = u;

    if (g-&gt;degree[u] == 0) {
        return;
    }

    int edgeCount = 0;
    int candidates[MAX_V];

    for (int v = 0; v &lt; g-&gt;vertexCount; v++) {
        if (g-&gt;adj[u][v] &gt; 0) {
            candidates[edgeCount++] = v;
        }
    }

    for (int i = 0; i &lt; edgeCount; i++) {
        int v = candidates[i];

        if (g-&gt;degree[u] == 1 || !isBridge(g, u, v)) {
            g-&gt;adj[u][v]--;
            g-&gt;adj[v][u]--;
            g-&gt;degree[u]--;
            g-&gt;degree[v]--;

            fleury(g, v, path, pathCount);
            return;
        }
    }
}
