C++<pre><code>class EulerPath {
private:
    vector&lt;vector&lt;int&gt;&gt; adj;
    int n;
    vector&lt;int&gt; path;

    void hierholzer(int u) {
        for (int v = 0; v &lt; n; v++) {
            while (adj[u][v] &gt; 0) {
                adj[u][v]--;
                adj[v][u]--;
                hierholzer(v);
            }
        }
        path.push_back(u);
    }

public:
    EulerPath(int n) : n(n), adj(n, vector&lt;int&gt;(n, 0)) {}

    void addEdge(int u, int v) {
        adj[u][v]++;
        adj[v][u]++;
    }

    vector&lt;int&gt; findEulerPath() {
        vector&lt;int&gt; degree(n);
        for (int i = 0; i &lt; n; i++) {
            for (int j = 0; j &lt; n; j++) {
                degree[i] += adj[i][j];
            }
        }

        int oddCount = 0;
        int start = 0;
        for (int i = 0; i &lt; n; i++) {
            if (degree[i] % 2) {
                oddCount++;
                start = i;
            }
        }

        if (oddCount != 0 &amp;&amp; oddCount != 2) {
            return {};
        }

        path.clear();
        hierholzer(start);
        reverse(path.begin(), path.end());
        return path;
    }
};

class HamiltonPath {
private:
    vector&lt;vector&lt;int&gt;&gt; adj;
    int n;
    vector&lt;int&gt; path;
    vector&lt;bool&gt; visited;

    bool dfs(int pos) {
        if (pos == n) {
            return true;
        }

        for (int v = 0; v &lt; n; v++) {
            if (!visited[v] &amp;&amp; adj[path[pos - 1]][v]) {
                path[pos] = v;
                visited[v] = true;

                if (dfs(pos + 1)) {
                    return true;
                }

                visited[v] = false;
            }
        }

        return false;
    }

public:
    HamiltonPath(int n) : n(n), adj(n, vector&lt;int&gt;(n, 0)) {}

    void addEdge(int u, int v) {
        adj[u][v] = adj[v][u] = 1;
    }

    vector&lt;int&gt; findHamiltonPath() {
        path.assign(n, -1);
        visited.assign(n, false);

        for (int start = 0; start &lt; n; start++) {
            path[0] = start;
            visited[start] = true;

            if (dfs(1)) {
                return path;
            }

            visited[start] = false;
        }

        return {};
    }
};
