C++<pre><code>class GraphColoring {
private:
    vector&lt;vector&lt;int&gt;&gt; adj;
    int n;
    vector&lt;int&gt; color;

    bool isSafe(int v, int c) {
        for (int u = 0; u &lt; n; u++) {
            if (adj[v][u] &amp;&amp; color[u] == c) {
                return false;
            }
        }
        return true;
    }

    bool solve(int m, int v) {
        if (v == n) return true;

        for (int c = 1; c &lt;= m; c++) {
            if (isSafe(v, c)) {
                color[v] = c;
                if (solve(m, v + 1)) return true;
                color[v] = 0;
            }
        }

        return false;
    }

public:
    GraphColoring(int n) : n(n), adj(n, vector&lt;int&gt;(n, 0)), color(n, 0) {}

    void addEdge(int u, int v) {
        adj[u][v] = adj[v][u] = 1;
    }

    vector&lt;int&gt; greedyColoring() {
        color.assign(n, 0);
        color[0] = 1;

        for (int v = 1; v &lt; n; v++) {
            set&lt;int&gt; usedColors;
            for (int u = 0; u &lt; n; u++) {
                if (adj[v][u] &amp;&amp; color[u] &gt; 0) {
                    usedColors.insert(color[u]);
                }
            }

            int c = 1;
            while (usedColors.count(c)) c++;
            color[v] = c;
        }

        return color;
    }

    int findChromaticNumber() {
        for (int m = 1; m &lt;= n; m++) {
            color.assign(n, 0);
            if (solve(m, 0)) {
                return m;
            }
        }
        return n;
    }

    vector&lt;int&gt; getColoring() const { return color; }
};
