// 合并两个有序数组
void merge(int arr[], int left, int mid, int right, int temp[]) {
    int i = left;      // 左数组起始
    int j = mid + 1;   // 右数组起始
    int k = left;      // 临时数组起始

    printf("  合并 [%d, %d] 和 [%d, %d]: ", left, mid, mid + 1, right);

    while (i &lt;= mid &amp;&amp; j &lt;= right) {
        if (arr[i] &lt;= arr[j]) {
            temp[k++] = arr[i++];
        } else {
            temp[k++] = arr[j++];
        }
    }

    // 处理剩余元素
    while (i &lt;= mid) temp[k++] = arr[i++];
    while (j &lt;= right) temp[k++] = arr[j++];

    // 复制回原数组
    for (i = left; i &lt;= right; i++) {
        arr[i] = temp[i];
    }

    // 打印
    for (i = left; i &lt;= right; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

