    // 将 pivot 放到正确位置
    int temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;

    // 打印
    for (int k = low; k &lt;= high; k++) {
        printf("%d ", arr[k]);
    }
    printf("\n");

    return i + 1;
}

void quickSort(int arr[], int low, int high) {
    if (low &gt;= high) return;

    int pi = partition(arr, low, high);

    // 递归排序两部分
    quickSort(arr, low, pi - 1);
    quickSort(arr, pi + 1, high);
}
