                while (left &lt; right &amp;&amp; arr[left] == arr[left + 1]) left++;
                while (left &lt; right &amp;&amp; arr[right] == arr[right - 1]) right--;

                left++;
                right--;
            } else if (sum &lt; target) {
                left++;
            } else {
                right--;
            }
        }
