Text Only<pre><code>问题: 在字符串 s 中找到包含 t 所有字符的最短子串

示例: s = "ADOBECODEBANC", t = "ABC"
</code></pre> C<pre><code>#include &lt;stdio.h&gt;
#include &lt;string.h&gt;
#include &lt;stdlib.h&gt;

char* minWindow(char *s, char *t) {
    int count[128] = {0};       // t 中各字符的需求量
    int required = 0;            // 需要的不同字符数

    // 统计 t 的字符
    for (int i = 0; t[i]; i++) {
        if (count[t[i]] == 0) required++;
        count[t[i]]++;
    }

    int left = 0, right = 0;
    int formed = 0;              // 已满足的字符数
    int windowCounts[128] = {0};

    int minLen = 1e9, start = 0;

    printf("最小覆盖子串:\n");
    printf("目标: %s\n", t);
    printf("源串: %s\n\n", s);

    while (s[right]) {
        // 扩展窗口
        char c = s[right];
        windowCounts[c]++;

        if (windowCounts[c] == count[c]) {
            formed++;
        }

        // 收缩窗口
        while (formed == required) {
            if (right - left + 1 &lt; minLen) {
                minLen = right - left + 1;
                start = left;
                printf("找到窗口: [%d, %d], 长度=%d, 子串=%.*s\n",
                       left, right, minLen, minLen, s + start);
            }

            char leftChar = s[left];
            windowCounts[leftChar]--;
            if (windowCounts[leftChar] &lt; count[leftChar]) {
                formed--;
            }
            left++;
        }

        right++;
    }

    if (minLen == 1e9) {
        printf("不存在覆盖子串\n");
        return "";
    }

    char *result = (char*)malloc(minLen + 1);
    strncpy(result, s + start, minLen);
    result[minLen] = '\0';

    printf("最小覆盖子串: %s\n", result);
    return result;
}
