C<pre><code>// 统计每一位的出现次数
int singleNumberII(int nums[], int n) {
    int result = 0;

    for (int i = 0; i &lt; 32; i++) {
        int sum = 0;
        for (int j = 0; j &lt; n; j++) {
            if ((nums[j] &gt;&gt; i) &amp; 1) {
                sum++;
            }
        }
        // 出现次数模3
        if (sum % 3) {
            result |= (1 &lt;&lt; i);
        }
    }

    return result;
}

// 状态机解法（更优）
int singleNumberII_StateMachine(int nums[], int n) {
    int ones = 0, twos = 0;

    for (int i = 0; i &lt; n; i++) {
        ones = (ones ^ nums[i]) &amp; ~twos;
        twos = (twos ^ nums[i]) &amp; ~ones;
    }

    return ones;
}
</code></pre>

