    int count = 1;            // 计数器

    for (int i = 1; i &lt; n; i++) {
        if (count == 0) {
            // 计数为0，更换候选
            candidate = nums[i];
            count = 1;
        } else if (nums[i] == candidate) {
            // 遇到相同元素，计数+1
            count++;
        } else {
            // 遇到不同元素，计数-1（抵消）
            count--;
        }
    }

    return candidate;
}
