        if (num == candidate1) {
            count1++;
        } else if (num == candidate2) {
            count2++;
        } else if (count1 == 0) {
            candidate1 = num;
            count1 = 1;
        } else if (count2 == 0) {
            candidate2 = num;
            count2 = 1;
        } else {
            count1--;
            count2--;
        }
    }

    // 验证
    count1 = count2 = 0;
    for (int num : nums) {
        if (num == candidate1) count1++;
        else if (num == candidate2) count2++;
    }

    std::vector&lt;int&gt; result;
    if (count1 &gt; n / 3) result.push_back(candidate1);
    if (count2 &gt; n / 3) result.push_back(candidate2);

    return result;
}
