    style D fill:#E8F5E9,stroke:#4CAF50</code></pre> C<pre><code>int subarraySum(int nums[], int n, int k) {
    int count = 0;
    int sum = 0;

    // 哈希表：记录前缀和出现的次数
    // 这里简化实现，实际应用用真正的哈希表
    int *hashMap = (int*)calloc(20001, sizeof(int));
    hashMap[10000] = 1;  // 初始：前缀和为0出现1次

    for (int i = 0; i &lt; n; i++) {
        sum += nums[i];

        // 查找 sum - k 出现的次数
        int target = sum - k + 10000;
        if (target &gt;= 0 &amp;&amp; target &lt;= 20000) {
            count += hashMap[target];
        }

        // 记录当前前缀和
        hashMap[sum + 10000]++;
    }

    free(hashMap);
    return count;
}
