C<pre><code>// 计算LPS数组
void computeLPS(const char *pattern, int *lps) {
    int m = strlen(pattern);
    int len = 0;    // 当前最长相同前后缀长度
    lps[0] = 0;     // LPS[0]总是0
    int i = 1;

    while (i &lt; m) {
        if (pattern[i] == pattern[len]) {
            // 可以扩展相同前后缀
            len++;
            lps[i] = len;
            i++;
        } else {
            if (len != 0) {
                // 回退到更短的相同前后缀
                len = lps[len - 1];
            } else {
                // 没有相同前后缀
                lps[i] = 0;
                i++;
            }
        }
    }
}

// KMP搜索
int kmpSearch(const char *text, const char *pattern) {
    int n = strlen(text);
    int m = strlen(pattern);

    if (m == 0) return 0;
    if (n &lt; m) return -1;

    int *lps = (int*)malloc(sizeof(int) * m);
    computeLPS(pattern, lps);

    int i = 0;  // 文本串指针
    int j = 0;  // 模式串指针

    while (i &lt; n) {
        if (pattern[j] == text[i]) {
            i++;
            j++;
        }

        if (j == m) {
            free(lps);
            return i - j;  // 找到匹配
        } else if (i &lt; n &amp;&amp; pattern[j] != text[i]) {
            if (j != 0) {
                j = lps[j - 1];  // 利用LPS跳转
            } else {
                i++;  // 完全不匹配，前进一步
            }
        }
    }

    free(lps);
    return -1;
}
</code></pre>

C<pre><code>// 坏字符启发式预处理
void badCharHeuristic(const char *pattern, int m, int badChar[256]) {
    // 初始化为-1
    for (int i = 0; i &lt; 256; i++) {
        badChar[i] = -1;
    }

    // 记录每个字符在模式串中最右出现的位置
    for (int i = 0; i &lt; m; i++) {
        badChar[(unsigned char)pattern[i]] = i;
    }
}

// BM搜索
int bmSearch(const char *text, const char *pattern) {
    int n = strlen(text);
    int m = strlen(pattern);

    int badChar[256];
    badCharHeuristic(pattern, m, badChar);

    int s = 0;  // 模式串相对于文本串的偏移
    while (s &lt;= n - m) {
        int j = m - 1;  // 从右向左匹配

        // 匹配时j递减
        while (j &gt;= 0 &amp;&amp; pattern[j] == text[s + j]) {
            j--;
        }

        if (j &lt; 0) {
            return s;  // 找到匹配
        } else {
            // 坏字符跳转
            int bcShift = j - badChar[(unsigned char)text[s + j]];
            s += (bcShift &gt; 1) ? bcShift : 1;
        }
    }

    return -1;
}
