C<pre><code>int rabinKarp(const char *text, const char *pattern) {
    int n = strlen(text);
    int m = strlen(pattern);
    int d = 256;   // 字符集大小
    int q = 101;   // 质数模数

    // 计算 h = d^(m-1) mod q
    int h = 1;
    for (int i = 0; i &lt; m - 1; i++) {
        h = (h * d) % q;
    }

    // 计算模式串和第一个窗口的哈希值
    int p = 0;  // 模式串哈希
    int t = 0;  // 文本串窗口哈希

    for (int i = 0; i &lt; m; i++) {
        p = (d * p + pattern[i]) % q;
        t = (d * t + text[i]) % q;
    }

    // 滑动窗口
    for (int i = 0; i &lt;= n - m; i++) {
        // 哈希值匹配，验证
        if (p == t) {
            int j;
            for (j = 0; j &lt; m; j++) {
                if (text[i + j] != pattern[j]) {
                    break;
                }
            }
            if (j == m) {
                return i;  // 找到匹配
            }
        }

        // 滚动哈希
        if (i &lt; n - m) {
            t = (d * (t - text[i] * h) + text[i + m]) % q;
            if (t &lt; 0) t += q;  // 保证正数
        }
    }

    return -1;
}
</code></pre>

