C++<pre><code>#include &lt;string&gt;
#include &lt;vector&gt;

class KMP {
private:
    std::string pattern;
    std::vector&lt;int&gt; lps;

    void computeLPS() {
        int m = pattern.length();
        lps.resize(m);
        int len = 0;

        for (int i = 1; i &lt; m; i++) {
            while (len &gt; 0 &amp;&amp; pattern[i] != pattern[len]) {
                len = lps[len - 1];
            }
            if (pattern[i] == pattern[len]) {
                len++;
            }
            lps[i] = len;
        }
    }

public:
    KMP(const std::string&amp; p) : pattern(p) {
        computeLPS();
    }

    int search(const std::string&amp; text) {
        int n = text.length();
        int m = pattern.length();

        for (int i = 0, j = 0; i &lt; n; i++) {
            while (j &gt; 0 &amp;&amp; text[i] != pattern[j]) {
                j = lps[j - 1];
            }
            if (text[i] == pattern[j]) {
                j++;
            }
            if (j == m) {
                return i - m + 1;
            }
        }
        return -1;
    }

    std::vector&lt;int&gt; findAll(const std::string&amp; text) {
        std::vector&lt;int&gt; result;
        int n = text.length();
        int m = pattern.length();

        for (int i = 0, j = 0; i &lt; n; i++) {
            while (j &gt; 0 &amp;&amp; text[i] != pattern[j]) {
                j = lps[j - 1];
            }
            if (text[i] == pattern[j]) {
                j++;
            }
            if (j == m) {
                result.push_back(i - m + 1);
                j = lps[j - 1];  // 继续搜索下一个匹配
            }
        }
        return result;
    }
};
