C<pre><code>long long power(long long base, long long exp, long long mod) {
    long long result = 1;
    base %= mod;

    while (exp &gt; 0) {
        if (exp &amp; 1) {
            result = result * base % mod;
        }
        base = base * base % mod;
        exp &gt;&gt;= 1;
    }

    return result;
}

int millerRabin(long long n, int k) {
    // 处理小数
    if (n &lt;= 1 || n == 4) return 0;
    if (n &lt;= 3) return 1;

    // 写成 n-1 = 2^r × d
    long long d = n - 1;
    while (d % 2 == 0) {
        d /= 2;
    }

    // 进行 k 次测试
    for (int i = 0; i &lt; k; i++) {
        long long a = 2 + rand() % (n - 4);
        long long x = power(a, d, n);

        if (x == 1 || x == n - 1) continue;

        // 二次探测
        while (d != n - 1) {
            x = x * x % n;
            d *= 2;

            if (x == 1) return 0;      // 确定是合数
            if (x == n - 1) break;     // 可能是素数
        }

        if (x != n - 1) return 0;      // 确定是合数
    }

    return 1;  // 很可能是素数
}
