    int steps = 0;

    while (current != target &amp;&amp; steps &lt; maxSteps) {
        // 收集邻居
        int degree = 0;
        int neighbors[100];

        for (int i = 0; i &lt; n; i++) {
            if (graph[current][i]) {
                neighbors[degree++] = i;
            }
        }

        if (degree == 0) return -1;  // 无法继续

        // 随机选择邻居
        current = neighbors[rand() % degree];
        steps++;
    }

    return (current == target) ? steps : -1;
}
