C<pre><code>int knapsackApprox(int weights[], int values[], int n, int W, double epsilon) {
    int maxVal = 0;
    for (int i = 0; i &lt; n; i++) {
        if (values[i] &gt; maxVal) maxVal = values[i];
    }

    int K = (int)(epsilon * maxVal / n);

    if (K == 0) K = 1;

    int *scaledValues = (int*)malloc(sizeof(int) * n);
    for (int i = 0; i &lt; n; i++) {
        scaledValues[i] = values[i] / K;
    }

    int totalValue = 0;
    for (int i = 0; i &lt; n; i++) {
        totalValue += scaledValues[i];
    }

    int **dp = (int**)malloc(sizeof(int*) * (n + 1));
    for (int i = 0; i &lt;= n; i++) {
        dp[i] = (int*)malloc(sizeof(int) * (totalValue + 1));
        for (int j = 0; j &lt;= totalValue; j++) {
            dp[i][j] = W + 1;
        }
    }
    dp[0][0] = 0;

    for (int i = 1; i &lt;= n; i++) {
        for (int j = 0; j &lt;= totalValue; j++) {
            dp[i][j] = dp[i - 1][j];
            if (j &gt;= scaledValues[i - 1]) {
                int prev = dp[i - 1][j - scaledValues[i - 1]] + weights[i - 1];
                if (prev &lt; dp[i][j]) {
                    dp[i][j] = prev;
                }
            }
        }
    }

    int result = 0;
    for (int j = totalValue; j &gt;= 0; j--) {
        if (dp[n][j] &lt;= W) {
            result = j * K;
            break;
        }
    }

    for (int i = 0; i &lt;= n; i++) free(dp[i]);
    free(dp);
    free(scaledValues);

    return result;
}
</code></pre>

C<pre><code>typedef struct {
    int u, v, weight;
} Edge;

int parent[MAX_V];

int find(int x) {
    while (parent[x] != x) x = parent[x];
    return x;
}

void unite(int x, int y) {
    parent[find(x)] = find(y);
}

int compareEdges(const void *a, const void *b) {
    return ((Edge*)a)-&gt;weight - ((Edge*)b)-&gt;weight;
}

int* mst(int graph[MAX_V][MAX_V], int n, int *mstSize) {
    Edge *edges = (Edge*)malloc(sizeof(Edge) * n * n);
    int edgeCount = 0;

    for (int i = 0; i &lt; n; i++) {
        for (int j = i + 1; j &lt; n; j++) {
            if (graph[i][j] &gt; 0) {
                edges[edgeCount++] = (Edge){i, j, graph[i][j]};
            }
        }
    }

    qsort(edges, edgeCount, sizeof(Edge), compareEdges);

    for (int i = 0; i &lt; n; i++) parent[i] = i;

    int *mstEdges = (int*)malloc(sizeof(int) * 2 * n);
    *mstSize = 0;

    for (int i = 0; i &lt; edgeCount; i++) {
        int u = edges[i].u;
        int v = edges[i].v;

        if (find(u) != find(v)) {
            unite(u, v);
            mstEdges[(*mstSize)++] = u;
            mstEdges[(*mstSize)++] = v;
        }
    }

    free(edges);
    return mstEdges;
}

int* preorder(int graph[MAX_V][MAX_V], int n, int start, int *orderSize) {
    int *order = (int*)malloc(sizeof(int) * n);
    int *stack = (int*)malloc(sizeof(int) * n);
    int top = 0, visited[MAX_V] = {0};

    stack[top++] = start;
    *orderSize = 0;

    while (top &gt; 0) {
        int u = stack[--top];

        if (!visited[u]) {
            visited[u] = 1;
            order[(*orderSize)++] = u;

            for (int v = n - 1; v &gt;= 0; v--) {
                if (graph[u][v] &amp;&amp; !visited[v]) {
                    stack[top++] = v;
                }
            }
        }
    }

    free(stack);
    return order;
}

int tspApprox(int graph[MAX_V][MAX_V], int n) {
    int mstSize;
    int *mstEdges = mst(graph, n, &amp;mstSize);

    int mstGraph[MAX_V][MAX_V];
    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; n; j++) {
            mstGraph[i][j] = 0;
        }
    }

    for (int i = 0; i &lt; mstSize; i += 2) {
        int u = mstEdges[i];
        int v = mstEdges[i + 1];
        mstGraph[u][v] = mstGraph[v][u] = 1;
    }

    int orderSize;
    int *order = preorder(mstGraph, n, 0, &amp;orderSize);

    int totalCost = 0;
    for (int i = 0; i &lt; orderSize - 1; i++) {
        totalCost += graph[order[i]][order[i + 1]];
    }
    totalCost += graph[order[orderSize - 1]][order[0]];

    free(mstEdges);
    free(order);

    return totalCost;
}
</code></pre>

