C<pre><code>#define MAX_N 100

typedef struct {
    int level;
    int profit;
    int weight;
    float bound;
} Node;

typedef struct {
    int weight[MAX_N];
    int value[MAX_N];
    int n;
    int capacity;
    float ratio[MAX_N];
} Knapsack;

void sortByRatio(Knapsack *kp) {
    for (int i = 0; i &lt; kp-&gt;n; i++) {
        kp-&gt;ratio[i] = (float)kp-&gt;value[i] / kp-&gt;weight[i];
    }

    for (int i = 0; i &lt; kp-&gt;n - 1; i++) {
        for (int j = 0; j &lt; kp-&gt;n - i - 1; j++) {
            if (kp-&gt;ratio[j] &lt; kp-&gt;ratio[j + 1]) {
                float tempR = kp-&gt;ratio[j];
                kp-&gt;ratio[j] = kp-&gt;ratio[j + 1];
                kp-&gt;ratio[j + 1] = tempR;

                int tempW = kp-&gt;weight[j];
                kp-&gt;weight[j] = kp-&gt;weight[j + 1];
                kp-&gt;weight[j + 1] = tempW;

                int tempV = kp-&gt;value[j];
                kp-&gt;value[j] = kp-&gt;value[j + 1];
                kp-&gt;value[j + 1] = tempV;
            }
        }
    }
}

float bound(Knapsack *kp, Node u) {
    if (u.weight &gt;= kp-&gt;capacity) {
        return 0;
    }

    float profitBound = u.profit;
    int j = u.level + 1;
    int totalWeight = u.weight;

    while (j &lt; kp-&gt;n &amp;&amp; totalWeight + kp-&gt;weight[j] &lt;= kp-&gt;capacity) {
        totalWeight += kp-&gt;weight[j];
        profitBound += kp-&gt;value[j];
        j++;
    }

    if (j &lt; kp-&gt;n) {
        profitBound += (kp-&gt;capacity - totalWeight) * kp-&gt;ratio[j];
    }

    return profitBound;
}

int knapsackBranchBound(Knapsack *kp) {
    sortByRatio(kp);

    Node queue[MAX_N * MAX_N];
    int front = 0, rear = 0;

    Node u, v;
    u.level = -1;
    u.profit = 0;
    u.weight = 0;
    u.bound = bound(kp, u);

    queue[rear++] = u;
    int maxProfit = 0;

    while (front &lt; rear) {
        u = queue[front++];

        if (u.bound &gt; maxProfit) {
            v.level = u.level + 1;

            v.weight = u.weight + kp-&gt;weight[v.level];
            v.profit = u.profit + kp-&gt;value[v.level];

            if (v.weight &lt;= kp-&gt;capacity &amp;&amp; v.profit &gt; maxProfit) {
                maxProfit = v.profit;
            }

            v.bound = bound(kp, v);

            if (v.bound &gt; maxProfit) {
                queue[rear++] = v;
            }

            v.weight = u.weight;
            v.profit = u.profit;
            v.bound = bound(kp, v);

            if (v.bound &gt; maxProfit) {
                queue[rear++] = v;
            }
        }
    }

    return maxProfit;
}
</code></pre>

C<pre><code>#define MAX_QUEUE 10000

typedef struct {
    Node data[MAX_QUEUE];
    int size;
} PriorityQueue;

void initPQ(PriorityQueue *pq) {
    pq-&gt;size = 0;
}

void swapNode(Node *a, Node *b) {
    Node temp = *a;
    *a = *b;
    *b = temp;
}

void push(PriorityQueue *pq, Node node) {
    int i = pq-&gt;size++;
    pq-&gt;data[i] = node;

    while (i &gt; 0 &amp;&amp; pq-&gt;data[(i - 1) / 2].bound &lt; pq-&gt;data[i].bound) {
        swapNode(&amp;pq-&gt;data[i], &amp;pq-&gt;data[(i - 1) / 2]);
        i = (i - 1) / 2;
    }
}

Node pop(PriorityQueue *pq) {
    Node result = pq-&gt;data[0];
    pq-&gt;data[0] = pq-&gt;data[--pq-&gt;size];

    int i = 0;
    while (2 * i + 1 &lt; pq-&gt;size) {
        int larger = 2 * i + 1;
        if (larger + 1 &lt; pq-&gt;size &amp;&amp; 
            pq-&gt;data[larger + 1].bound &gt; pq-&gt;data[larger].bound) {
            larger++;
        }

        if (pq-&gt;data[i].bound &gt;= pq-&gt;data[larger].bound) break;

        swapNode(&amp;pq-&gt;data[i], &amp;pq-&gt;data[larger]);
        i = larger;
    }

    return result;
}

int isEmpty(PriorityQueue *pq) {
    return pq-&gt;size == 0;
}

int knapsackPQ(Knapsack *kp) {
    sortByRatio(kp);

    PriorityQueue pq;
    initPQ(&amp;pq);

    Node u, v;
    u.level = -1;
    u.profit = 0;
    u.weight = 0;
    u.bound = bound(kp, u);

    push(&amp;pq, u);
    int maxProfit = 0;

    while (!isEmpty(&amp;pq)) {
        u = pop(&amp;pq);

        if (u.bound &gt; maxProfit) {
            v.level = u.level + 1;

            v.weight = u.weight + kp-&gt;weight[v.level];
            v.profit = u.profit + kp-&gt;value[v.level];

            if (v.weight &lt;= kp-&gt;capacity &amp;&amp; v.profit &gt; maxProfit) {
                maxProfit = v.profit;
            }

            v.bound = bound(kp, v);
            if (v.bound &gt; maxProfit) {
                push(&amp;pq, v);
            }

            v.weight = u.weight;
            v.profit = u.profit;
            v.bound = bound(kp, v);

            if (v.bound &gt; maxProfit) {
                push(&amp;pq, v);
            }
        }
    }

    return maxProfit;
}
