        if (!node-&gt;visited[i]) {
            int minDist = INF;
            for (int j = 0; j &lt; n; j++) {
                if (i != j &amp;&amp; dist[i][j] &lt; minDist) {
                    minDist = dist[i][j];
                }
            }
            bound += minDist;
        }
    }

    return bound;
}

int tspBranchBound() {
    PriorityQueue pq;
    initPQ(&amp;pq);

    TSPNode start;
    start.city = 0;
    start.cost = 0;
    start.pathLen = 1;
    start.path[0] = 0;
    for (int i = 0; i &lt; n; i++) {
        start.visited[i] = 0;
    }
    start.visited[0] = 1;

    push(&amp;pq, *(Node*)&amp;start);

    int minCost = INF;
    int bestPath[MAX_CITIES];

    while (!isEmpty(&amp;pq)) {
        Node nodeData = pop(&amp;pq);
        TSPNode *curr = (TSPNode*)&amp;nodeData;

        if (curr-&gt;cost &gt;= minCost) continue;

        if (curr-&gt;pathLen == n) {
            int totalCost = curr-&gt;cost + dist[curr-&gt;city][0];
            if (totalCost &lt; minCost) {
                minCost = totalCost;
                for (int i = 0; i &lt; n; i++) {
                    bestPath[i] = curr-&gt;path[i];
                }
            }
            continue;
        }

        for (int next = 0; next &lt; n; next++) {
            if (!curr-&gt;visited[next]) {
                TSPNode child;
                child.city = next;
                child.cost = curr-&gt;cost + dist[curr-&gt;city][next];
                child.pathLen = curr-&gt;pathLen + 1;

                for (int i = 0; i &lt; curr-&gt;pathLen; i++) {
                    child.path[i] = curr-&gt;path[i];
                }
                child.path[curr-&gt;pathLen] = next;

                for (int i = 0; i &lt; n; i++) {
                    child.visited[i] = curr-&gt;visited[i];
                }
                child.visited[next] = 1;

                int bound = tspBound(&amp;child);
                if (bound &lt; minCost) {
                    push(&amp;pq, *(Node*)&amp;child);
                }
            }
        }
    }

    return minCost;
}
