void knapsackInit(Individual *ind) {
    for (int i = 0; i &lt; kp.n; i++) {
        ind-&gt;genes[i] = rand() % 2;
    }
}

double knapsackFitness(Individual *ind) {
    int totalWeight = 0;
    int totalValue = 0;

    for (int i = 0; i &lt; kp.n; i++) {
        if (ind-&gt;genes[i]) {
            totalWeight += kp.weight[i];
            totalValue += kp.value[i];
        }
    }

    if (totalWeight &gt; kp.capacity) {
        return 0;
    }

    return totalValue;
}
