C<pre><code>#include &lt;string.h&gt;
#include &lt;stdlib.h&gt;

char* minWindow(char *s, char *t) {
    int sLen = strlen(s);
    int tLen = strlen(t);

    if (sLen &lt; tLen) return "";

    // 统计t中字符频率
    int need[256] = {0};
    int needCount = 0;
    for (int i = 0; i &lt; tLen; i++) {
        if (need[(unsigned char)t[i]] == 0) {
            needCount++;
        }
        need[(unsigned char)t[i]]++;
    }

    // 滑动窗口
    int window[256] = {0};
    int have = 0;
    int left = 0;
    int minLen = sLen + 1;
    int start = -1;

    for (int right = 0; right &lt; sLen; right++) {
        char c = s[right];
        window[(unsigned char)c]++;

        // 如果这个字符的数量达到了需要
        if (window[(unsigned char)c] == need[(unsigned char)c]) {
            have++;
        }

        // 当满足所有字符需求时，尝试缩小窗口
        while (have == needCount) {
            // 更新最小窗口
            int windowLen = right - left + 1;
            if (windowLen &lt; minLen) {
                minLen = windowLen;
                start = left;
            }

            // 移除左边界字符
            char leftChar = s[left];
            if (window[(unsigned char)leftChar] == need[(unsigned char)leftChar]) {
                have--;
            }
            window[(unsigned char)leftChar]--;
            left++;
        }
    }

    if (start == -1) return "";

    char *result = (char*)malloc(sizeof(char) * (minLen + 1));
    strncpy(result, s + start, minLen);
    result[minLen] = '\0';
    return result;
}
