C++<pre><code>#include &lt;string&gt;
#include &lt;vector&gt;
#include &lt;deque&gt;
#include &lt;unordered_map&gt;

// 滑动窗口最大值
std::vector&lt;int&gt; maxSlidingWindow(std::vector&lt;int&gt;&amp; nums, int k) {
    std::vector&lt;int&gt; result;
    std::deque&lt;int&gt; dq;  // 存储下标

    for (int i = 0; i &lt; nums.size(); i++) {
        // 移除过期元素
        while (!dq.empty() &amp;&amp; dq.front() &lt;= i - k) {
            dq.pop_front();
        }

        // 维护单调递减队列
        while (!dq.empty() &amp;&amp; nums[dq.back()] &lt; nums[i]) {
            dq.pop_back();
        }

        dq.push_back(i);

        if (i &gt;= k - 1) {
            result.push_back(nums[dq.front()]);
        }
    }

    return result;
}

// 最长无重复子串
int lengthOfLongestSubstring(std::string s) {
    std::unordered_map&lt;char, int&gt; charIndex;
    int maxLen = 0;
    int left = 0;

    for (int right = 0; right &lt; s.length(); right++) {
        if (charIndex.count(s[right]) &amp;&amp; charIndex[s[right]] &gt;= left) {
            left = charIndex[s[right]] + 1;
        }
        charIndex[s[right]] = right;
        maxLen = std::max(maxLen, right - left + 1);
    }

    return maxLen;
}

// 最小覆盖子串
std::string minWindow(std::string s, std::string t) {
    std::unordered_map&lt;char, int&gt; need, window;
    for (char c : t) need[c]++;

    int left = 0, have = 0;
    int minLen = s.length() + 1, start = -1;

    for (int right = 0; right &lt; s.length(); right++) {
        window[s[right]]++;

        if (need.count(s[right]) &amp;&amp; window[s[right]] == need[s[right]]) {
            have++;
        }

        while (have == need.size()) {
            if (right - left + 1 &lt; minLen) {
                minLen = right - left + 1;
                start = left;
            }

            if (need.count(s[left]) &amp;&amp; window[s[left]] == need[s[left]]) {
                have--;
            }
            window[s[left]]--;
            left++;
        }
    }

    return start == -1 ? "" : s.substr(start, minLen);
}
