C<pre><code>// 和&gt;=target的最短子数组长度
int minSubArrayLen(int target, int arr[], int n) {
    int minLen = n + 1;
    int sum = 0;
    int left = 0;

    for (int right = 0; right &lt; n; right++) {
        sum += arr[right];

        while (sum &gt;= target) {
            if (right - left + 1 &lt; minLen) {
                minLen = right - left + 1;
            }
            sum -= arr[left];
            left++;
        }
    }

    return minLen == n + 1 ? 0 : minLen;
}
