C<pre><code>int numSubarrayProductLessThanK(int arr[], int n, int k) {
    if (k &lt;= 1) return 0;

    int count = 0;
    int product = 1;
    int left = 0;

    for (int right = 0; right &lt; n; right++) {
        product *= arr[right];

        while (product &gt;= k) {
            product /= arr[left];
            left++;
        }

        // 以right结尾的所有子数组都满足
        count += right - left + 1;
    }

    return count;
}
