TypeScript<pre><code>export function materialAdmonitionsRender(text: string): string {
  let renderResult = text
  let match: RegExpExecArray | null = null
  // 匹配字符串中所有以!!!开始的内容（直到遇到另一个
  // !（图片、下一个块）、#（标题）、`（代码块）、=（内容选项卡）、
  // -、+（无序列表、行分隔符）、[（链接）、$(公式)、|（表格）、{（特殊块）、&lt;（html语法）
  // :(icon，emojis)、*（加粗）、~（删除线）、&gt;（引用）、\r?\n（空行）
  // 或者字符串的结尾）
  const regex = /!!!([\s\S]*?)(?=\n[!#`=\-+[$|{&lt;:*~&gt;\S]|$)/g
  // 使用全局搜索来查找所有匹配项，匹配到的字符串，已经去掉了前缀和后缀
  while ((match = regex.exec(renderResult)) !== null) {
    //console.log('match[1]', match[1])
    const content = materialParserAdmonitions(match[1])
    const renderHtml =
      `&lt;div class="admonition ${content.type}"&gt;` +
      `&lt;p class="admonition-title"&gt;${content.title}&lt;/p&gt;` +
      `${content.content}&lt;/div&gt;`
    renderResult = renderResult.replace(match[0], renderHtml)
    //console.log('renderResult', renderResult)
  }

  return renderResult
}
</code></pre> <p>其实就是一个字符串匹配的动作，匹配后的字符串，安装规则解析，然后填写对应的html标签。设置对应的样式表，样式表是从网站上copy下来的。</p>

TypeScript<pre><code>// event-bus.js
const EventBus = {
  // 你可以使用 ref 创建一个响应式的数据源（如果需要的话）
  // 也可以使用 Map 或其他数据结构来存储事件和回调
  callbacks: new Map(),

  $on(eventName, callback) {
    if (!this.callbacks.has(eventName)) {
      this.callbacks.set(eventName, [])
    }
    this.callbacks.get(eventName).push(callback)
  },
  $emit(eventName, payload) {
    if (this.callbacks.has(eventName)) {
      this.callbacks.get(eventName).forEach((callback) =&gt; {
        callback(payload)
      })
    }
  },
  $off(eventName, callback) {
    if (this.callbacks.has(eventName)) {
      this.callbacks.set(
        eventName,
        this.callbacks.get(eventName).filter((cb) =&gt; cb !== callback)
      )
    }
  },
  // 修改 $off 方法以支持移除所有事件的所有监听器
  $offAll() {
    this.callbacks.clear()
  }
}

export default EventBus
